return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=1; plural=0;','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'ចូលទៅកាន់កម្មវិធីជំនួយស្វែងរក','Activate %s' => 'ធ្វើឱ្យសកម្ម %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> ទាមទារ <strong>%2$s</strong> ដើម្បីដំឡើង និងធ្វើឱ្យសកម្ម។ <a href="%4$s">%3$s</a>','Enter your code here' => 'បញ្ចូលលេខកូដរបស់អ្នកនៅទីនេះ','Add %s' => 'បន្ថែម %s','Remove' => 'ដកចេញ','Order number and receipt will be sent to this email address.' => 'លេខបញ្ជាទិញ និងបង្កាន់ដៃនឹងត្រូវបានផ្ញើទៅកាន់អាសយដ្ឋានអ៊ីមែលនេះ។','Apartment, unit, building, floor, etc.' => 'ផ្ទះល្វែង យូនីត អាគារ ជាន់។ល។','Shipping phone' => 'ទូរស័ព្ទដឹកជញ្ជូន','Only used for shipping-related questions.' => 'ប្រើសម្រាប់តែសំណួរទាក់ទងនឹងការដឹកជញ្ជូនប៉ុណ្ណោះ។','Single step' => 'ជំហានតែមួយ','Click to go to the order summary' => 'ចុច​ដើម្បី​ទៅ​កាន់​សេចក្ដី​សង្ខេប​នៃ​ការ​បញ្ជា​ទិញ','Cart total:' => 'សរុបរទេះ៖','Proceed to %s' => 'បន្តទៅ %s','Proceed to contact' => 'បន្តទំនាក់ទំនង','Proceed to shipping' => 'បន្តទៅការដឹកជញ្ជូន','Proceed to billing' => 'បន្តទៅវិក័យប័ត្រ','Proceed to payment' => 'បន្តទៅការទូទាត់','Shipping method' => 'វិធីសាស្រ្តដឹកជញ្ជូន','Additional notes' => 'កំណត់ចំណាំបន្ថែម','Payment method' => 'វិធីបង់ប្រាក់','Step %1$s of %2$s' => 'ជំហាន %1$s នៃ %2$s','Change: %s' => 'ផ្លាស់ប្តូរ៖ %s','Not selected yet.' => 'មិនទាន់បានជ្រើសរើសទេ។','Same as shipping address' => 'ដូចគ្នានឹងអាសយដ្ឋានដឹកជញ្ជូន','Same as billing address' => 'ដូចគ្នានឹងអាសយដ្ឋានវិក្កយបត្រ','Order summary' => 'សេចក្តីសង្ខេបនៃការបញ្ជាទិញ','Edit cart' => 'កែសម្រួលរទេះ','Did you mean %s?' => 'តើអ្នកចង់មានន័យថា %s ទេ?','Change email address to: {suggestion-value}' => 'ផ្លាស់ប្តូរអាសយដ្ឋានអ៊ីមែលទៅ៖ {suggestion-value}','This is a required field.' => 'នេះគឺជាវាលដែលត្រូវការ។','This is not a valid email address.' => 'នេះមិនមែនជាអាសយដ្ឋានអ៊ីមែលត្រឹមត្រូវទេ។','This field does not match the related field value.' => 'វាលនេះមិនត្រូវគ្នានឹងតម្លៃវាលដែលពាក់ព័ន្ធទេ។','The CPF number "{cpf_number}" is invalid.' => 'លេខ CPF &quot;{cpf_number}&quot; មិនត្រឹមត្រូវទេ។','The CNPJ number "{cnpj_number}" is invalid.' => 'លេខ CNPJ &quot;{cnpj_number}&quot; មិនត្រឹមត្រូវទេ។','(Required)' => '(ទាមទារ)','Checkout Header - Desktop' => 'បឋមកថាពិនិត្យចេញ - ផ្ទៃតុ','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'បង្ហាញធាតុក្រាហ្វិកនៅលើបឋមកថាបង់ប្រាក់សម្រាប់អេក្រង់ធំ។ បង្ហាញតែប្រសិនបើប្រើបឋមកថាពិនិត្យចេញរបស់កម្មវិធីជំនួយ។','Checkout Header - Mobile' => 'បឋមកថាពិនិត្យចេញ - ទូរស័ព្ទ','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'បង្ហាញធាតុក្រាហ្វិកខាងក្រោមបឋមកថាបង់ប្រាក់សម្រាប់ឧបករណ៍ចល័ត។ បង្ហាញតែប្រសិនបើប្រើបឋមកថាពិនិត្យចេញរបស់កម្មវិធីជំនួយ។','Checkout Sidebar' => 'របារចំហៀងពិនិត្យចេញ','Display widgets on the checkout sidebar after the order summary.' => 'បង្ហាញធាតុក្រាហ្វិកនៅលើរបារចំហៀងពិនិត្យចេញ បន្ទាប់ពីសេចក្តីសង្ខេបនៃការបញ្ជាទិញ។','Checkout Order Summary' => 'សង្ខេបការបញ្ជាទិញ','Display widgets inside the order summary at the checkout page.' => 'បង្ហាញធាតុក្រាហ្វិកនៅខាងក្នុងសេចក្ដីសង្ខេបនៃការបញ្ជាទិញនៅទំព័រពិនិត្យចេញ។','Checkout Below Place Order' => 'ពិនិត្យ​ចេញ​ក្រោម​ការ​បញ្ជា​ទិញ','Display widgets below the place order button at the checkout page.' => 'បង្ហាញធាតុក្រាហ្វិកខាងក្រោមប៊ូតុងបញ្ជាទីកន្លែងនៅទំព័រពិនិត្យចេញ។','Checkout Footer' => 'បាតកថាពិនិត្យចេញ','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'បង្ហាញធាតុក្រាហ្វិកនៅលើបាតកថាបង់ប្រាក់ចេញ។ បង្ហាញតែប្រសិនបើប្រើបាតកថាពិនិត្យចេញរបស់កម្មវិធីជំនួយ។','Classic' => 'បុរាណ','Boxed' => 'ប្រអប់','Split' => 'បំបែក','Minimalist' => 'តិចតួចបំផុត។','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'កម្មវិធីជំនួយពិនិត្យចេញ និងកាលបរិច្ឆេទដឹកជញ្ជូនដោយ CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>យើងបានរកឃើញថាអ្នកកំពុងប្រើកម្មវិធីជំនួយ Delivery &amp; Pickup Date Time សម្រាប់ WooCommerce (ឥតគិតថ្លៃ និង PRO) ដោយ CodeRockz ។ ការរួមបញ្ចូលជាមួយកម្មវិធីជំនួយទាំងនេះត្រូវបានផ្លាស់ទីទៅ Fluid Checkout PRO ។</p>','Upgrade to PRO' => 'ដំឡើងកំណែទៅ PRO','Fluid Checkout database updated successfully' => 'បានធ្វើបច្ចុប្បន្នភាពមូលដ្ឋានទិន្នន័យ Fluid Checkout ដោយជោគជ័យ','The database changes where applied successfully.' => 'មូលដ្ឋានទិន្នន័យផ្លាស់ប្តូរកន្លែងដែលអនុវត្តដោយជោគជ័យ។','Dismiss' => 'ច្រានចោល','Fluid Checkout database update' => 'ការធ្វើបច្ចុប្បន្នភាពមូលដ្ឋានទិន្នន័យ Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ការផ្លាស់ប្តូរមួយចំនួនចំពោះមូលដ្ឋានទិន្នន័យត្រូវបានទាមទារ។ ដូចទៅនឹងការធ្វើបច្ចុប្បន្នភាពណាមួយដែរ យើងណែនាំអ្នកឱ្យ <strong>ធ្វើការបម្រុងទុកពេញលេញនៃគេហទំព័ររបស់អ្នកមុនពេលបន្ត</strong> ។','Update database' => 'ធ្វើបច្ចុប្បន្នភាពមូលដ្ឋានទិន្នន័យ','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout មិនឆបគ្នាជាមួយប្លង់ពិនិត្យចេញ Divi Builder ទេ។','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout ត្រូវការទម្រង់ពិនិត្យចេញដែលមានមូលដ្ឋានលើ WooCommerce shortcode បុរាណដើម្បីដំណើរការ។ នៅពេលប្រើ Divi Builder ដើម្បីប្ដូររូបរាង និងអារម្មណ៍នៃទំព័រពិនិត្យចេញ កូដខ្លីបុរាណត្រូវបានជំនួសដោយធាតុក្រាហ្វិកផ្ទាល់ខ្លួនពី Divi Builder សម្រាប់ផ្នែកនីមួយៗនៃទំព័រពិនិត្យចេញ។ ធាតុក្រាហ្វិកផ្ទាល់ខ្លួនទាំងនេះមិនត្រូវគ្នាជាមួយ Fluid Checkout ទេ។</p><p> សូមកែសម្រួលទំព័រទូទាត់របស់អ្នកដោយជំនួសធាតុក្រាហ្វិក Divi Builder ជាមួយនឹងធាតុក្រាហ្វិកអត្ថបទដែលមានលេខកូដខ្លី <code>[woocommerce_checkout]</code></p>','Edit the checkout page' => 'កែសម្រួលទំព័របង់ប្រាក់ចេញ','Read the documentation.' => 'អានឯកសារ។','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'មុខងារពិនិត្យចេញច្រើនជំហានរបស់ Germanized PRO ត្រូវតែបិទនៅពេលប្រើ Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'នៅពេលប្រើ Fluid Checkout មុខងារ multistep ពីកម្មវិធីជំនួយ Germanized PRO ក្លាយជាមិនចាំបាច់ ហើយអាចបណ្តាលឱ្យ <strong>មានកំហុសធ្ងន់ធ្ងរ ខណៈពេលដែលកំពុងដំណើរការការបញ្ជាទិញថ្មី</strong> ។ សូមបិទមុខងារពិនិត្យចេញច្រើនជំហានរបស់ Germanized PRO នៅក្នុងការកំណត់កម្មវិធីជំនួយ។','Go to Germanized settings' => 'ចូលទៅកាន់ការកំណត់ Germanized','Thanks for choosing Fluid Checkout!' => 'អរគុណសម្រាប់ការជ្រើសរើស Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'អ្នកបានប្រើកម្មវិធីជំនួយមួយរយៈឥឡូវនេះ។ តើអ្នកចូលចិត្តវាយ៉ាងម៉េចដែរ?<br> សូមផ្តល់ឱ្យយើងនូវការវាយតម្លៃរហ័ស យើងពេញចិត្តចំពោះរាល់មតិកែលម្អ ហើយវាលើកទឹកចិត្តយើងឱ្យបន្តកែលម្អកម្មវិធីជំនួយ :)','Rate the plugin' => 'វាយតម្លៃកម្មវិធីជំនួយ','I need help!' => 'ខ្ញុំត្រូវការជំនួយ!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'លក្ខណៈពិសេសមួយចំនួនរបស់ WooCommerce Checkout Manager ដោយ Quadlayers ប្រហែលជាមិនដំណើរការដូចការរំពឹងទុកទេ នៅពេលប្រើវាជាមួយ Fluid Checkout។ សូមអាន <a href="%s">ឯកសាររបស់យើង</a> សម្រាប់ព័ត៌មានបន្ថែម និងដំណោះស្រាយជំនួស។','Read documentation' => 'អានឯកសារ','Don\'t show this again' => 'កុំបង្ហាញវាម្តងទៀត','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'គំរូរចនាច្រើនទៀត','Optimized cart page' => 'ទំព័ររទេះដែលប្រសើរឡើង','Optimized order received / thank you page' => 'ការបញ្ជាទិញដែលប្រសើរឡើងបានទទួល / អរគុណទំព័រ','Edit cart contents at checkout page' => 'កែសម្រួលមាតិការទេះនៅទំព័របង់ប្រាក់','Account matching / user matching' => 'ការផ្គូផ្គងគណនី / ការផ្គូផ្គងអ្នកប្រើប្រាស់','Trust symbols on the cart and thank you pages' => 'និមិត្តសញ្ញាទុកចិត្តនៅលើរទេះ និងទំព័រអរគុណ','More positions for the coupon code on the checkout page' => 'មុខតំណែងបន្ថែមសម្រាប់លេខកូដប័ណ្ណនៅលើទំព័រពិនិត្យចេញ','International phone numbers' => 'លេខទូរស័ព្ទអន្តរជាតិ','Gift messages and packing slips' => 'សារអំណោយ និងប័ណ្ណវេចខ្ចប់','Local pickup and in-store collection' => 'ការប្រមូលផលក្នុងស្រុក និងការប្រមូលនៅក្នុងហាង','EU-VAT Assistant' => 'EU-VAT ជំនួយការ','I already have it – Hide this offer' => 'ខ្ញុំមានវារួចហើយ - លាក់ការផ្តល់ជូននេះ។','Activated' => 'បានធ្វើឱ្យសកម្ម','Address book' => 'សៀវភៅអាសយដ្ឋាន','Select an image' => 'ជ្រើសរើសរូបភាព','Cart layout' => 'ប្លង់រទេះ','Cart optimizations' => 'ការបង្កើនប្រសិទ្ធភាពរទេះ','Enable cart page optimizations' => 'បើកការបង្កើនប្រសិទ្ធភាពទំព័ររទេះ','Header and footer template' => 'គំរូបឋមកថា និងបាតកថា','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'គ្រប់គ្រងថាតើត្រូវប្រើបឋមកថា និងបាតកថាទំព័រដែលគ្មានការរំខាន ឬរក្សាបឋមកថា និងបាតកថានៃរចនាប័ទ្មសកម្មបច្ចុប្បន្ន។','Distraction free header and footer' => 'បឋមកថា និងបាតកថាគ្មានការរំខាន','Theme\'s header and footer' => 'បឋមកថា និងបាតកថារបស់ប្រធានបទ','Cart elements' => 'ធាតុរទេះ','Make the order summary stay visible on the cart page while scrolling' => 'ធ្វើឱ្យសេចក្ដីសង្ខេបនៃការបញ្ជាទិញនៅតែអាចមើលឃើញនៅលើទំព័ររទេះខណៈពេលកំពុងរមូរ','Coupon codes' => 'លេខកូដប័ណ្ណ','Hidden' => 'លាក់','Before the cart items section' => 'មុនពេលផ្នែកធាតុរទេះ','Inside the cart items section' => 'នៅខាងក្នុងផ្នែកធាតុរទេះ','After the cart items section' => 'បន្ទាប់ពីផ្នែកធាតុរទេះ','Before the shipping section' => 'មុនពេលផ្នែកដឹកជញ្ជូន','After the shipping section' => 'បន្ទាប់ពីផ្នែកដឹកជញ្ជូន','Before the order summary' => 'មុនពេលសេចក្តីសង្ខេបនៃការបញ្ជាទិញ','Inside the order summary' => 'នៅខាងក្នុងសេចក្តីសង្ខេបនៃការបញ្ជាទិញ','Before the order totals' => 'មុនពេលការបញ្ជាទិញសរុប','After the order totals' => 'បន្ទាប់ពីការបញ្ជាទិញសរុប','After the order summary' => 'បន្ទាប់ពីសេចក្តីសង្ខេបនៃការបញ្ជាទិញ','Shipping' => 'ការដឹកជញ្ជូន','Select position where to display the shipping costs and calculator on the cart page.' => 'ជ្រើសរើសទីតាំងដែលត្រូវបង្ហាញថ្លៃដឹកជញ្ជូន និងម៉ាស៊ីនគិតលេខនៅលើទំព័ររទេះ។','Display as a cart section' => 'បង្ហាញជាផ្នែករទេះ','Cross-sells' => 'លក់ដាច់','Select position where to display the cross-sells section on the cart page.' => 'ជ្រើសរើសទីតាំងដែលត្រូវបង្ហាញផ្នែកលក់ឆ្លងនៅលើទំព័ររទេះ។','Before the cart actions' => 'មុនពេលសកម្មភាពរទេះ','After the cart actions' => 'បន្ទាប់ពីសកម្មភាពរទេះ','Layout of cross-sell items on the cart page.' => 'ប្លង់នៃទំនិញឆ្លងកាត់នៅលើទំព័ររទេះ។','Optimized horizontal cross-sells layout' => 'ប្លង់លក់ឆ្លងផ្តេកដែលបានធ្វើឱ្យប្រសើរ','Theme\'s cross-sells layout' => 'ប្លង់លក់ឆ្លងរបស់ប្រធានបទ','Number of cross-sell items to display on the cart page' => 'ចំនួននៃទំនិញលក់ដាច់ដែលត្រូវបង្ហាញនៅលើទំព័ររទេះ','Add widget areas to the cart page' => 'បន្ថែមតំបន់ធាតុក្រាហ្វិកទៅទំព័ររទេះ','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'តំបន់ធាតុក្រាហ្វិកទាំងនេះត្រូវបានប្រើដើម្បីបន្ថែមនិមិត្តសញ្ញាទុកចិត្ត និងផ្លាកសញ្ញាជឿទុកចិត្តនៅលើទំព័ររទេះ។','Checkout' => 'ពិនិត្យចេញ','Checkout layout' => 'ប្លង់ពិនិត្យចេញ','Design template' => 'គំរូរចនា','Dark mode' => 'របៀបងងឹត','Enable dark mode' => 'បើកមុខងារងងឹត','Logo image' => 'រូបភាពនិមិត្តសញ្ញា','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'ជ្រើសរើសរូបភាពដែលត្រូវបង្ហាញនៅលើបឋមកថាទំព័របង់ប្រាក់។ អនុវត្តតែនៅពេលប្រើបឋមកថា និងបាតកថាគ្មានការរំខាន។','Header background color' => 'ពណ៌ផ្ទៃខាងក្រោយបឋមកថា','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'ជ្រើសរើសពណ៌ផ្ទៃខាងក្រោយសម្រាប់បឋមកថាទំព័របង់ប្រាក់។ អនុវត្តតែនៅពេលប្រើបឋមកថា និងបាតកថាគ្មានការរំខាន។','HTML color value. ie: #f3f3f3' => 'តម្លៃពណ៌ HTML ។ ឧ៖ #f3f3f3','Page background color' => 'ពណ៌ផ្ទៃខាងក្រោយទំព័រ','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'ជ្រើសរើសពណ៌ផ្ទៃខាងក្រោយសម្រាប់ទំព័របង់ប្រាក់។ ពណ៌ត្រូវបានអនុវត្តទៅធាតុ <em>រាងកាយ</em> ។','Footer background color' => 'ពណ៌ផ្ទៃខាងក្រោយបាតកថា','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'ជ្រើសរើសពណ៌ផ្ទៃខាងក្រោយសម្រាប់បាតកថាទំព័របង់ប្រាក់។ អនុវត្តតែនៅពេលប្រើបឋមកថា និងបាតកថាគ្មានការរំខាន។','Progress bar' => 'របារវឌ្ឍនភាព','Display the checkout progress bar when using multi-step checkout layout' => 'បង្ហាញរបារដំណើរការពិនិត្យចេញ នៅពេលប្រើប្លង់ពិនិត្យចេញច្រើនជំហាន','Make the checkout progress bar stay visible while scrolling' => 'ធ្វើឱ្យរបារដំណើរការពិនិត្យចេញនៅតែអាចមើលឃើញខណៈពេលកំពុងរមូរ','Express checkout' => 'ការទូទាត់ចេញរហ័ស','Enable the express checkout section' => 'បើកផ្នែកទូទាត់រហ័ស','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'បង្ហាញផ្នែកបង់ប្រាក់ចេញភ្លាមៗនៅពេលចេញលុយនៅពេលដែលច្រកផ្លូវទូទាត់ដែលគាំទ្របានបើកមុខងារនេះ។','Display express checkout buttons in one line for larger screens' => 'បង្ហាញប៊ូតុងទូទាត់រហ័សក្នុងបន្ទាត់តែមួយសម្រាប់អេក្រង់ធំ','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'មិនអើពើនឹងកន្លែងបង់ប្រាក់បន្ថែមដែលត្រូវការនៅពេលបង់ប្រាក់ជាមួយនឹងច្រកចេញទូទាត់រហ័សដែលត្រូវគ្នា។','Make the order summary stay visible while scrolling' => 'ធ្វើ​ឱ្យ​សេចក្ដី​សង្ខេប​នៃ​ការ​បញ្ជា​ទិញ​នៅ​តែ​មើល​ឃើញ​ពេល​រមូរ','Choose a background color for the order summary section.' => 'ជ្រើសរើសពណ៌ផ្ទៃខាងក្រោយសម្រាប់ផ្នែកសង្ខេបនៃការបញ្ជាទិញ។','Highlight the order totals row in the order summary table' => 'បន្លិចជួរសរុបនៃការបញ្ជាទិញនៅក្នុងតារាងសង្ខេបនៃការបញ្ជាទិញ','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'មានប្រយោជន៍បំផុតនៅពេលដែលផ្នែកសង្ខេបនៃការបញ្ជាទិញមិនមានពណ៌ផ្ទៃខាងក្រោយដែលបានបន្លិច។ ក៏អាចអនុវត្តចំពោះរទេះ ការបញ្ជាទិញបានទទួល និងមើលទំព័រការបញ្ជាទិញ នៅពេលប្រើ Fluid Checkout PRO ។','Action link on the order summary at checkout.' => 'តំណសកម្មភាពនៅលើសេចក្តីសង្ខេបនៃការបញ្ជាទិញនៅពេលចេញ។','Edit cart link' => 'កែសម្រួលតំណរទេះ','Cart items count' => 'រាប់ធាតុរទេះ','Link to shop page' => 'ភ្ជាប់ទៅទំព័រហាង','Cart items' => 'ធាតុរទេះ','Hide cart items errors at the checkout page' => 'លាក់កំហុសរបស់ទំនិញរទេះនៅទំព័របង់ប្រាក់','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'កុំបង្ហាញសារកំហុសរបស់ធាតុរទេះនៅផ្នែកខាងលើនៃទំព័របង់ប្រាក់។ នៅពេលដាក់ស្នើទម្រង់បង់ប្រាក់ដើម្បីបញ្ចប់ការទិញ សារកំហុសទាំងនេះនឹងត្រូវបានបង្ហាញជានិច្ច។','Place order' => 'ដាក់បញ្ជា','Define the position to display "Place order" and terms checkbox section.' => 'កំណត់ទីតាំងដើម្បីបង្ហាញ &quot;ការបញ្ជាទិញ&quot; និងផ្នែកប្រអប់ធីកពាក្យ។','Some options might not be compatible with some plugins and themes.' => 'ជម្រើសខ្លះអាចមិនត្រូវគ្នាជាមួយកម្មវិធីជំនួយ និងស្បែកមួយចំនួន។','Below the payment section' => 'ខាងក្រោមផ្នែកបង់ប្រាក់','Below the order summary' => 'ខាងក្រោមសេចក្តីសង្ខេបនៃការបញ្ជាទិញ','Both below the payment section and the order summary' => 'ទាំងខាងក្រោមផ្នែកទូទាត់ និងសេចក្តីសង្ខេបនៃការបញ្ជាទិញ','Add widget areas to the checkout page' => 'បន្ថែមតំបន់ធាតុក្រាហ្វិកទៅទំព័របង់ប្រាក់','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'តំបន់ធាតុក្រាហ្វិកទាំងនេះត្រូវបានប្រើដើម្បីបន្ថែមនិមិត្តសញ្ញាទុកចិត្ត និងផ្លាកសញ្ញាជឿទុកចិត្តនៅលើទំព័រពិនិត្យចេញ។','Display the coupon codes section title' => 'បង្ហាញចំណងជើងផ្នែក លេខកូដប័ណ្ណ','Select position where to display the coupon codes section on the checkout page.' => 'ជ្រើសរើសទីតាំងដែលត្រូវបង្ហាញផ្នែកលេខកូដប័ណ្ណនៅលើទំព័រពិនិត្យចេញ។','Before the checkout steps' => 'មុនពេលចេញដំណើរ','As a substep before payment methods' => 'ជា​ជំហាន​បន្ទាប់​មុន​នឹង​វិធី​បង់ប្រាក់','As a substep after payment methods' => 'ជាជំហានបន្ទាប់បន្ទាប់ពីវិធីបង់ប្រាក់','Default button style' => 'រចនាប័ទ្មប៊ូតុងលំនាំដើម','"Add" link button' => 'ប៊ូតុងភ្ជាប់ &quot;បន្ថែម&quot;','Checkout fields' => 'វាលពិនិត្យចេញ','Optional fields' => 'វាលស្រេចចិត្ត','Hide optional fields behind a link button' => 'លាក់វាលស្រេចចិត្តនៅពីក្រោយប៊ូតុងតំណ','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'វាត្រូវបានផ្ដល់អនុសាសន៍ឱ្យរក្សាជម្រើសនេះធីកដើម្បីកាត់បន្ថយចំនួននៃវាលបញ្ចូលដែលបើកចំហ <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">សូមអានការស្រាវជ្រាវ</a> ។','Do not hide "Address line 2" fields behind a link button' => 'កុំលាក់វាល &quot;អាសយដ្ឋាន 2&quot; នៅខាងក្រោយប៊ូតុងភ្ជាប់','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'ត្រូវបានណែនាំតែនៅពេលដែលអតិថិជនភាគច្រើនពិតជាត្រូវការវាល &quot;អាសយដ្ឋាន 2&quot; ឬនៅពេលទទួលបានអាសយដ្ឋានដឹកជញ្ជូនត្រឹមត្រូវគឺមានសារៈសំខាន់ (ឧ. ប្រសិនបើការដឹកជញ្ជូនអាហារ និងផលិតផលដែលអាចបំផ្លាញបានផ្សេងទៀត)។','Billing address' => 'អាសយដ្ឋានចេញវិក្កយបត្រ','Select position where to display the billing address section on the checkout page.' => 'ជ្រើសរើសទីតាំងដែលត្រូវបង្ហាញផ្នែកអាសយដ្ឋានវិក្កយបត្រនៅលើទំព័រទូទាត់។','As a step before shipping' => 'ជាជំហានមុនពេលដឹកជញ្ជូន','As a sub-step before the shipping address section' => 'ជាជំហានរងមុនផ្នែកអាសយដ្ឋានដឹកជញ្ជូន','As a sub-step after the shipping address section' => 'ជាជំហានរងបន្ទាប់ពីផ្នែកអាសយដ្ឋានដឹកជញ្ជូន','As a step after shipping' => 'ជាជំហានបន្ទាប់ពីការដឹកជញ្ជូន','As a sub-step before the payment section' => 'ជាជំហានរងមុនផ្នែកបង់ប្រាក់','Force billing and shipping addresses to the same (single section)' => 'បង្ខំអាសយដ្ឋានវិក្កយបត្រ និងដឹកជញ្ជូនទៅដូចគ្នា (ផ្នែកតែមួយ)','Checkbox for "Same as shipping/billing address" checked by default' => 'ប្រអប់ធីកសម្រាប់ &quot;ដូចគ្នានឹងអាសយដ្ឋានដឹកជញ្ជូន/វិក្កយបត្រ&quot; ត្រូវបានធីកតាមលំនាំដើម','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'ប្រអប់ធីក &quot;ដូចគ្នានឹងអាសយដ្ឋានដឹកជញ្ជូន&quot; នឹងចាប់ផ្តើមដូចដែលបានគូសតាមលំនាំដើម នៅពេលដែលផ្នែកអាសយដ្ឋានដឹកជញ្ជូនត្រូវបានបង្ហាញដំបូង។<br> ប្រអប់ធីក &quot;ដូចគ្នានឹងអាសយដ្ឋានវិក្កយបត្រ&quot; នឹងចាប់ផ្តើមដូចដែលបានគូសតាមលំនាំដើម នៅពេលដែលផ្នែកអាសយដ្ឋានវិក្កយបត្រត្រូវបានបង្ហាញដំបូង។<br> វាត្រូវបានផ្ដល់អនុសាសន៍ឱ្យទុកជម្រើសនេះធីកដើម្បីកាត់បន្ថយចំនួននៃវាលបញ្ចូលដែលបានបើកនៅពេលពិនិត្យចេញ <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">សូមអានការស្រាវជ្រាវ</a> ។','Highlight the billing address section in the checkout form' => 'បន្លិចផ្នែកអាសយដ្ឋានវិក្កយបត្រនៅក្នុងទម្រង់បង់ប្រាក់ចេញ','Shipping address' => 'អាសយដ្ឋានដឹកជញ្ជូន','Highlight the shipping address section in the checkout form' => 'បន្លិចផ្នែកអាសយដ្ឋានដឹកជញ្ជូនក្នុងទម្រង់បង់ប្រាក់ចេញ','Shipping methods' => 'វិធីសាស្រ្តដឹកជញ្ជូន','Choose in which position to display the shipping methods section.' => 'ជ្រើសរើសទីតាំងណាមួយដើម្បីបង្ហាញផ្នែកវិធីដឹកជញ្ជូន។','Before shipping address' => 'មុនពេលដឹកជញ្ជូនអាសយដ្ឋាន','After shipping address' => 'បន្ទាប់ពីអាសយដ្ឋានដឹកជញ្ជូន','Local pickup' => 'មកយកក្នុងស្រុក','Removes shipping address section when a local pickup shipping method is selected.' => 'ដកផ្នែកអាសយដ្ឋានដឹកជញ្ជូនចេញ នៅពេលដែលវិធីសាស្ត្រដឹកជញ្ជូនតាមតំបន់ត្រូវបានជ្រើសរើស។','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'ជំនួសអាសយដ្ឋានដឹកជញ្ជូនជាមួយនឹងទីតាំងចំណុចទទួល នៅពេលដែលវិធីសាស្ត្រដឹកជញ្ជូនតាមតំបន់ត្រូវបានជ្រើសរើស។','Choose which address to save as the shipping address for local pickup orders.' => 'ជ្រើសរើសអាសយដ្ឋានណាមួយដែលត្រូវរក្សាទុកជាអាសយដ្ឋានដឹកជញ្ជូនសម្រាប់ការបញ្ជាទិញក្នុងស្រុក។','Save the selected pickup location' => 'រក្សាទុក​ទីតាំង​ទទួល​បាន​ជ្រើសរើស','Save same as the billing address' => 'រក្សាទុកដូចគ្នានឹងអាសយដ្ឋានវិក្កយបត្រ','Do not save any shipping address' => 'កុំរក្សាទុកអាសយដ្ឋានដឹកជញ្ជូនណាមួយឡើយ។','Company name field for shipping address' => 'វាលឈ្មោះក្រុមហ៊ុនសម្រាប់អាសយដ្ឋានដឹកជញ្ជូន','Change visibility for the company name field for the shipping address section on the checkout form.' => 'ផ្លាស់ប្តូរភាពមើលឃើញសម្រាប់វាលឈ្មោះក្រុមហ៊ុនសម្រាប់ផ្នែកអាសយដ្ឋានដឹកជញ្ជូននៅលើទម្រង់បង់ប្រាក់ចេញ។','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'ប្រសិនបើវាលត្រូវបានកំណត់ជា &quot;ស្រេចចិត្ត&quot; ដែលជាស្ថានភាពមើលឃើញលំនាំដើមនោះ គ្មានការផ្លាស់ប្តូរណាមួយនឹងត្រូវបានអនុវត្តដើម្បីអនុញ្ញាតឱ្យកម្មវិធីជំនួយផ្សេងទៀតអនុវត្តការផ្លាស់ប្តូរណាមួយដែលពួកគេត្រូវការ។','Hidden (remove field)' => 'លាក់ (លុបវាល)','Optional' => 'ស្រេចចិត្ត','Required' => 'ទាមទារ','Add shipping phone field to the checkout form.' => 'បញ្ចូលប្រអប់ទូរស័ព្ទដឹកជញ្ជូនទៅទម្រង់បង់ប្រាក់ចេញ។','Choose in which step to display the shipping phone field.' => 'ជ្រើសរើសក្នុងជំហានណាមួយដើម្បីបង្ហាញប្រអប់ទូរស័ព្ទដឹកជញ្ជូន។','Contact step' => 'ជំហានទំនាក់ទំនង','Billing phone' => 'ទូរស័ព្ទចេញវិក្កយបត្រ','Add billing phone field to the checkout form.' => 'បញ្ចូលប្រអប់ទូរស័ព្ទចេញវិក្កយបត្រទៅទម្រង់បង់ប្រាក់ចេញ។','Choose in which step to display the billing phone field.' => 'ជ្រើសរើសក្នុងជំហានណាមួយ ដើម្បីបង្ហាញប្រអប់ទូរស័ព្ទចេញវិក្កយបត្រ។','Show country code beside the flag' => 'បង្ហាញលេខកូដប្រទេសក្បែរទង់ជាតិ','Show an example of a valid phone number inside phone fields' => 'បង្ហាញឧទាហរណ៍នៃលេខទូរស័ព្ទដែលមានសុពលភាពនៅក្នុងប្រអប់ទូរស័ព្ទ','Do not change placeholders' => 'កុំប្តូរកន្លែងដាក់','Show if not defined' => 'បង្ហាញប្រសិនបើមិនបានកំណត់','Always show' => 'បង្ហាញជានិច្ច','Order notes' => 'កំណត់ចំណាំបញ្ជាទិញ','Define the visibility of the additional order notes field.' => 'កំណត់ភាពមើលឃើញនៃវាលកំណត់ចំណាំលំដាប់បន្ថែម។','Gift options' => 'ជម្រើសអំណោយ','Allow customers to add a gift message and other gift related options to the order.' => 'អនុញ្ញាតឱ្យអតិថិជនបន្ថែមសារអំណោយ និងជម្រើសទាក់ទងនឹងអំណោយផ្សេងទៀតទៅក្នុងការបញ្ជាទិញ។','Display the gift message as part of the order details table instead of a separate section' => 'បង្ហាញសារអំណោយជាផ្នែកនៃតារាងព័ត៌មានលម្អិតនៃការបញ្ជាទិញជំនួសឱ្យផ្នែកដាច់ដោយឡែក','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'ជម្រើសនេះប៉ះពាល់ដល់ទំព័របញ្ជាក់ការបញ្ជាទិញ (ទំព័រអរគុណ) និងព័ត៌មានលម្អិតអំពីការបញ្ជាទិញនៅលើទំព័រគណនី អ៊ីមែល និងសន្លឹកវេចខ្ចប់។','Account matching' => 'ការផ្គូផ្គងគណនី','Enable the account matching feature' => 'បើកមុខងារផ្គូផ្គងគណនី','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'ភ្ជាប់ការបញ្ជាទិញរបស់អតិថិជនភ្ញៀវជាមួយនឹងគណនីដែលមានស្រាប់របស់ពួកគេ នៅពេលដែលគណនីមានរួចហើយជាមួយនឹងព័ត៌មានលម្អិតទំនាក់ទំនងរបស់អតិថិជន។','Display message when an account exists with the email address provided' => 'បង្ហាញសារនៅពេលដែលគណនីមានជាមួយអាសយដ្ឋានអ៊ីមែលដែលបានផ្តល់','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'ជំនួសកន្លែងបង្កើតគណនីដោយការជូនដំណឹង និងជម្រើសដើម្បីចូល។ ក្នុងបរិបទមួយចំនួន វាអាចត្រូវបានណែនាំឱ្យទុកជម្រើសនេះឱ្យបិទដើម្បីការពារភាពឯកជនរបស់អតិថិជន។','Dashboard' => 'ផ្ទាំងគ្រប់គ្រង','Integrations' => 'សមាហរណកម្ម','License keys' => 'សោអាជ្ញាប័ណ្ណ','Visit our website for more information about our plugins and add-ons.' => 'សូមចូលទៅកាន់គេហទំព័ររបស់យើងសម្រាប់ព័ត៌មានបន្ថែមអំពីកម្មវិធីជំនួយ និងកម្មវិធីបន្ថែមរបស់យើង។','Order pay page' => 'បញ្ជាទិញទំព័របង់ប្រាក់','Order pay' => 'បញ្ជាទិញបង់ប្រាក់','Enable order pay page optimizations' => 'បើកដំណើរការការបង្កើនប្រសិទ្ធភាពទំព័របង់ប្រាក់','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ផ្លាស់ប្តូរប្លង់នៃទំព័រទូទាត់ការបញ្ជាទិញសម្រាប់ការបញ្ជាទិញដែលមានស្រាប់ដែលរង់ចាំការទូទាត់ពីអតិថិជន។','Add widget areas to the order pay page' => 'បន្ថែមតំបន់ធាតុក្រាហ្វិកទៅទំព័របង់ប្រាក់បញ្ជាទិញ','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'តំបន់ធាតុក្រាហ្វិកទាំងនេះត្រូវបានប្រើដើម្បីបន្ថែមនិមិត្តសញ្ញាទុកចិត្ត និងផ្លាកសញ្ញាជឿទុកចិត្តនៅលើទំព័របង់ប្រាក់បញ្ជាទិញ។','Thank you page & order details layout' => 'អរគុណ Page &amp; Order ប្លង់លំអិត','Order details optimizations' => 'ការបង្កើនប្រសិទ្ធភាពព័ត៌មានលម្អិតនៃការបញ្ជាទិញ','Enable thank you page and order details optimizations' => 'បើកដំណើរការទំព័រអរគុណ និងការបង្កើនប្រសិទ្ធភាពព័ត៌មានលម្អិតនៃការបញ្ជាទិញ','Changes the layout of order details on the thank you page and account pages.' => 'ផ្លាស់ប្តូរប្លង់នៃព័ត៌មានលម្អិតនៃការបញ្ជាទិញនៅលើទំព័រអរគុណ និងទំព័រគណនី។','Enable order details customizations on email notifications' => 'បើកដំណើរការ​ការ​កំណត់​ព័ត៌មានលម្អិត​តាម​បំណង​លើ​ការ​ជូន​ដំណឹង​តាម​អ៊ីមែល','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'បង្ហាញផ្នែកថ្មី និងផ្លាស់ប្តូរលំដាប់នៃផ្នែកនៅលើការជូនដំណឹងតាមអ៊ីមែល។ រចនាប័ទ្មនៃព័ត៌មានលម្អិតនៃការបញ្ជាទិញនៅលើការជូនដំណឹងតាមអ៊ីមែលនៅតែមិនផ្លាស់ប្តូរ។','Thank you page' => 'សូមអរគុណទំព័រ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'ជម្រើសទាំងនេះប៉ះពាល់ដល់ទំព័រអរគុណ ដែលត្រូវបានគេស្គាល់ថាជាការបញ្ជាទិញបានទទួល ឬទំព័របញ្ជាក់ការបញ្ជាទិញ។','Order details layout' => 'បញ្ជាទិញប្លង់លម្អិត','Display the order details with wide layout on the thank you page' => 'បង្ហាញព័ត៌មានលម្អិតនៃការបញ្ជាទិញជាមួយនឹងប្លង់ធំទូលាយនៅលើទំព័រអរគុណ','Add widget areas to the thank you page' => 'បន្ថែមតំបន់ធាតុក្រាហ្វិកទៅទំព័រអរគុណ','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'តំបន់ធាតុក្រាហ្វិកទាំងនេះត្រូវបានប្រើដើម្បីបន្ថែមនិមិត្តសញ្ញាទុកចិត្ត និងផ្លាកសញ្ញាជឿទុកចិត្តនៅលើទំព័រអរគុណ។','Order actions' => 'បញ្ជា​សកម្មភាព','Choose in which position to display the order actions.' => 'ជ្រើសរើសទីតាំងណាមួយដើម្បីបង្ហាញសកម្មភាពលំដាប់។','Inside the order overview' => 'ទិដ្ឋភាពទូទៅនៃការបញ្ជាទិញ','After the order overview' => 'បន្ទាប់ពីទិដ្ឋភាពទូទៅនៃការបញ្ជាទិញ','After order sections' => 'បន្ទាប់ពីផ្នែកបញ្ជាទិញ','Order status' => 'ស្ថានភាពបញ្ជាទិញ','Display the order status progress bar' => 'បង្ហាញរបារវឌ្ឍនភាពស្ថានភាពការបញ្ជាទិញ','Choose in which position to display the section.' => 'ជ្រើសរើសទីតាំងណាមួយដើម្បីបង្ហាញផ្នែក។','After the order overview and payment instructions' => 'បន្ទាប់ពីទិដ្ឋភាពទូទៅនៃការបញ្ជាទិញ និងការណែនាំអំពីការទូទាត់','Before the order items section' => 'មុនពេលផ្នែកបញ្ជាទិញ','Inside the order items section' => 'នៅខាងក្នុងផ្នែកធាតុបញ្ជាទិញ','After the order items section' => 'បន្ទាប់ពីផ្នែកនៃការបញ្ជាទិញ','On the sidebar' => 'នៅលើរបារចំហៀង','Order downloads' => 'បញ្ជាទិញការទាញយក','Gift message' => 'សារអំណោយ','Tools' => 'ឧបករណ៍','Troubleshooting' => 'ការដោះស្រាយបញ្ហា','Debug options' => 'ជម្រើសបំបាត់កំហុស','Debug mode' => 'របៀបបំបាត់កំហុស','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'ការប្រើរបៀបបំបាត់កំហុសប៉ះពាល់ដល់ដំណើរការគេហទំព័រ។ ប្រើជម្រើសនេះតែពេលកំពុងដោះស្រាយបញ្ហាប៉ុណ្ណោះ។','Load unminified assets' => 'ផ្ទុក​ទ្រព្យ​សកម្ម​ដែល​មិន​ទាន់​កំណត់','Enhanced select fields' => 'កែលម្អ​វាល​ជ្រើសរើស','Fix automatic zoom-in on form fields' => 'ជួសជុលការពង្រីកដោយស្វ័យប្រវត្តិនៅលើវាលទម្រង់','Set <code>font-size</code> inside form fields to 16px' => 'កំណត់ <code>font-size</code> នៅក្នុងវាលទម្រង់ទៅ 16px','Fluid Checkout' => 'ការត្រួតពិនិត្យសារធាតុរាវ','Settings' => 'ការកំណត់','Support' => 'គាំទ្រ','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">ដំឡើងកំណែទៅ PRO</a> ដើម្បីដោះសោជម្រើសច្រើនទៀត។','(PRO)' => '(PRO)','(experimental)' => '(ពិសោធន៍)','Please verify your phone number.' => 'សូមផ្ទៀងផ្ទាត់លេខទូរស័ព្ទរបស់អ្នក។','The Bluehost Plugin' => 'កម្មវិធីជំនួយ Bluehost','Custom fields' => 'វាលផ្ទាល់ខ្លួន','Enable custom shipping email field' => 'បើកដំណើរការប្រអប់អ៊ីមែលដឹកជញ្ជូនផ្ទាល់ខ្លួន','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'នៅពេលបើកដំណើរការ ប្រអប់អ៊ីមែលដឹកជញ្ជូនពីកម្មវិធីជំនួយ Bluehost នឹងត្រូវបានបញ្ចូលទៅក្នុងទម្រង់បង់ប្រាក់ចេញ។','Captcha Pro by BestWebSoft' => 'Captcha Pro ដោយ BestWebSoft','Captcha position' => 'ទីតាំង Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'កំណត់ទីតាំងដើម្បីបង្ហាញផ្នែក captcha ។ មុខតំណែងមួយចំនួនប្រហែលជាមិនដំណើរការទេ អាស្រ័យលើប្រភេទ captcha ដែលបានជ្រើសរើស។','Selecting a pickup point is required before proceeding.' => 'ការជ្រើសរើសចំណុចទៅយកគឺចាំបាច់មុនពេលបន្ត។','Pickup point' => 'ចំណុចទៅយក','Pickup point not selected yet.' => 'ចំណុចទៅយកមិនទាន់បានជ្រើសរើសទេ។','Pickup point:' => 'ចំណុចទៅយក៖','Mailchimp for WooCommerce' => 'Mailchimp សម្រាប់ WooCommerce','Subscribe checkbox' => 'ប្រអប់ធីកជាវ','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'បដិសេធទីតាំងសម្រាប់ប្រអប់ធីកជាវនៅលើទំព័រពិនិត្យចេញ ហើយតែងតែបង្ហាញវានៅលើជំហានទំនាក់ទំនង','Before Shipping Address' => 'មុនពេលអាសយដ្ឋានដឹកជញ្ជូន','(originally "%s")' => '(ដើមឡើយ &quot;%s&quot;)','After Shipping Address' => 'បន្ទាប់ពីអាសយដ្ឋានដឹកជញ្ជូន','Selecting a collection point is required when shipping with FermoPoint.' => 'ការជ្រើសរើសចំណុចប្រមូលគឺចាំបាច់នៅពេលដឹកជញ្ជូនជាមួយ FermoPoint ។','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'ប្រសិនបើធីក ជូនដំណឹងអំពីការវាយអក្សរនៅក្នុងអ៊ីមែលទៅអ្នកប្រើប្រាស់។ (មុខងារនេះត្រូវបានបិទដោយសារតែ Fluid Checkout ផ្តល់នូវលក្ខណៈពិសេស។ ការផ្លាស់ប្តូរទៅជម្រើសនេះនឹងមិនមានប្រសិទ្ធិភាពទេ)','Enable Mail Check: (disabled feature)' => 'បើកដំណើរការពិនិត្យសំបុត្រ៖ (មុខងារបិទ)','Carrier:' => 'ក្រុមហ៊ុនដឹកជញ្ជូន៖','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - ទីផ្សារអ៊ីម៉ែល WooCommerce','Sign up checkbox position' => 'ចុះឈ្មោះទីតាំងប្រអប់ធីក','Move the sign up checkbox to the contact step' => 'ផ្លាស់ទីប្រអប់ធីកចុះឈ្មោះទៅជំហានទំនាក់ទំនង','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'នៅពេលបើកដំណើរការ ប្រអប់ធីកនឹងត្រូវបានផ្លាស់ទីទៅជំហានទំនាក់ទំនងដោយឯករាជ្យពីទីតាំងបង្ហាញដែលបានកំណត់នៅក្នុងការកំណត់កម្មវិធីជំនួយ Sendinblue ។','Theme Betheme' => 'ប្រធានបទ Betheme','Checkout progress' => 'ដំណើរការពិនិត្យចេញ','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'បង្ហាញផ្នែកជំហានចេញពី Betheme នៅលើទំព័របង់ប្រាក់ រទេះ និងការបញ្ជាទិញដែលបានទទួល។','Theme Fennik' => 'ប្រធានបទ Fennik','Breadcrumbs' => 'ម្សៅនំប៉័ង','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'បញ្ចេញផ្នែក breadcrumbs ពីប្រធានបទ Fennik នៅពេលប្រើបឋមកថា និងបាតកថា Fluid Checkout ។','Theme Go' => 'ប្រធានបទទៅ','My account layout' => 'ប្លង់គណនីរបស់ខ្ញុំ','Enable wide layout on "My account" page.' => 'បើកដំណើរការប្លង់ធំទូលាយនៅលើទំព័រ &quot;គណនីរបស់ខ្ញុំ&quot; ។','Theme Impreza' => 'ប្រធានបទ Impreza','Header' => 'បឋមកថា','Spacing for site header at the checkout page (in pixels)' => 'គម្លាតសម្រាប់បឋមកថាគេហទំព័រនៅទំព័រពិនិត្យចេញ (គិតជាភីកសែល)','Only applicable when using the Impreza theme header at the checkout page.' => 'អាចអនុវត្តបានតែនៅពេលប្រើបឋមកថា Impreza នៅទំព័រពិនិត្យចេញ។','Theme Kapee' => 'ប្រធានបទ Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'បង្ហាញផ្នែកជំហាននៃការដកប្រាក់ពីប្រធានបទ Kapee នៅលើទំព័របង់ប្រាក់ រទេះ និងការបញ្ជាទិញដែលបានទទួល។','Theme Porto' => 'ប្រធានបទ Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'បង្ហាញផ្នែកជំហានចេញប្រាក់ពីប្រធានបទ Porto នៅលើទំព័របង់ប្រាក់ រទេះ និងការបញ្ជាទិញដែលបានទទួល។','Theme Pressmart' => 'ប្រធានបទ Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'បង្ហាញផ្នែកជំហាននៃការដកប្រាក់ពីប្រធានបទ Pressmart នៅលើទំព័របង់ប្រាក់ រទេះ និងការបញ្ជាទិញដែលបានទទួល។','Theme The Gem' => 'ប្រធានបទ ត្បូង','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'បង្ហាញផ្នែកជំហាននៃការចេញប្រាក់ពីប្រធានបទ The Gem នៅពេលប្រើបឋមកថា និងបាតកថា Fluid Checkout ។','Theme Woodmart' => 'ប្រធានបទ Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'បង្ហាញផ្នែកជំហានពិនិត្យចេញពីប្រធានបទ Woodmart នៅពេលប្រើបឋមកថា និងបាតកថា Fluid Checkout ។','Checkout options' => 'ជម្រើសបង់ប្រាក់ចេញ','Disable the theme checkout options' => 'បិទជម្រើសបង់ប្រាក់ចេញតាមប្រធានបទ','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'ជម្រើសបង្ហាញរូបភាពផលិតផល វាលបរិមាណ ប៊ូតុងលុបចេញ និងតំណភ្ជាប់ទៅកាន់ទំព័រផលិតផលដែលបានបន្ថែមដោយស្បែកត្រូវបានបិទតាមលំនាំដើម។','Theme Atomion' => 'ប្រធានបទ Atomion','Order progress' => 'ការបញ្ជាទិញរីកចម្រើន','Display order progress from the theme' => 'បង្ហាញវឌ្ឍនភាពលំដាប់ពីប្រធានបទ','Display the form field labels visible on the page' => 'បង្ហាញស្លាកវាលទម្រង់ដែលអាចមើលឃើញនៅលើទំព័រ','It is recommended to keep this option enabled for a better user experience.' => 'វាត្រូវបានផ្ដល់អនុសាសន៍ឱ្យរក្សាជម្រើសនេះឱ្យដំណើរការសម្រាប់បទពិសោធន៍អ្នកប្រើប្រាស់កាន់តែប្រសើរ។','Theme ZK Nito' => 'ប្រធានបទ ZK Nito','Add extra fields to the checkout form' => 'បន្ថែមវាលបន្ថែមទៅទម្រង់បង់ប្រាក់ចេញ','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'បន្ថែមអ៊ីមែលដឹកជញ្ជូន និងប្រអប់ទូរស័ព្ទដឹកជញ្ជូនបន្ថែមទៅផ្នែកអាសយដ្ឋានដឹកជញ្ជូន។','Go to the home page' => 'ទៅកាន់ទំព័រដើម','Skip to content' => 'រំលងទៅមាតិកា','Create an account' => 'បង្កើតគណនីមួយ។','Log in to your account' => 'ចូលទៅគណនីរបស់អ្នក។','Already have an account?' => 'មានគណនីរួចហើយ?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'ចូលជា %1$s ។ <a href="%2$s">ចេញ</a>','Your order has a total amount due of %s. No further payment is needed.' => 'ការបញ្ជាទិញរបស់អ្នកមានចំនួនសរុបដល់ទៅ %s ។ មិនចាំបាច់បង់ប្រាក់បន្ថែមទេ។','Close and continue with checkout' => 'បិទ ហើយបន្តជាមួយនឹងការបង់ប្រាក់ចេញ','Continue' => 'បន្ត','Parcel terminal' => 'ស្ថានីយ Parcel','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>ធាតុក្រាហ្វិកនេះត្រូវបានជំនួសដោយ Fluid Checkout ។</p><p> នៅពេលប្រើ Fluid Checkout ទំព័រពិនិត្យចេញត្រូវប្រើកូដខ្លី WooCommerce ដើម <code>[woocommerce_checkout]</code> ដើម្បីដំណើរការបានត្រឹមត្រូវ។</p><p> សម្រាប់ព័ត៌មានបន្ថែម សូមចូលទៅកាន់ឯកសារ Fluid Checkout។</p>','Theme The7' => 'ប្រធានបទ ៧','Additional header sections' => 'ផ្នែកបឋមកថាបន្ថែម','Output additional header sections if enabled in the theme settings.' => 'បញ្ចេញផ្នែកបឋមកថាបន្ថែម ប្រសិនបើបានបើកនៅក្នុងការកំណត់ស្បែក។','More information' => 'ព័ត៌មានបន្ថែម','Pick a Locker' => 'ជ្រើសរើស Locker','Page template' => 'គំរូទំព័រ','Use `Order confirmation` page template for block-based themes' => 'ប្រើគំរូទំព័រ &#39;ការបញ្ជាក់ការបញ្ជាទិញ&#39; សម្រាប់ស្បែកផ្អែកលើប្លុក','Only applies when using a block-based theme.' => 'អនុវត្តតែនៅពេលប្រើស្បែកផ្អែកលើប្លុកប៉ុណ្ណោះ។','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'ទម្រង់បង់ប្រាក់','Apply styles to the Stripe payment form fields' => 'អនុវត្តរចនាប័ទ្មទៅវាលទម្រង់បែបបទបង់ប្រាក់ Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'នៅពេលបើកដំណើរការ Fluid Checkout នឹងអនុវត្តរចនាប័ទ្មដែលបានធ្វើឱ្យប្រសើរសម្រាប់ភាពឆបគ្នាជាមួយកម្មវិធីជំនួយ។ អ្នកប្រហែលជាចង់បិទវា ប្រសិនបើអ្នកកំពុងប្រើរចនាប័ទ្មផ្ទាល់ខ្លួនសម្រាប់វាលទម្រង់បែបបទបង់ប្រាក់ Stripe។','Theme Nyture' => 'ប្រធានបទ Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'បង្ហាញផ្នែកជំហាននៃការដកប្រាក់ចេញពីស្បែក Nyture នៅពេលប្រើ Fluid Checkout ។','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'អនុញ្ញាតឱ្យអតិថិជនធ្វើការទូទាត់សម្រាប់ការបញ្ជាទិញដែលត្រូវបានបង្កើតដោយដៃដោយអ្នកគ្រប់គ្រងហាង ឬមិនបានបញ្ចប់អំឡុងពេលបង់ប្រាក់ចេញ។','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'កម្មវិធីជំនួយ WooCommerce Checkout Manager ដោយ Quadlayers មិនត្រូវគ្នាជាមួយ Fluid Checkout ទេ។','Company name field for billing address' => 'វាលឈ្មោះក្រុមហ៊ុនសម្រាប់អាសយដ្ឋានវិក្កយបត្រ','Change visibility for the company name field for the billing address section on the checkout form.' => 'ផ្លាស់ប្តូរភាពមើលឃើញសម្រាប់វាលឈ្មោះក្រុមហ៊ុនសម្រាប់ផ្នែកអាសយដ្ឋានវិក្កយបត្រនៅលើទម្រង់បង់ប្រាក់ចេញ។','Theme Bookshelf' => 'ធ្នើសៀវភៅប្រធានបទ','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'បង្ហាញផ្នែកជំហាននៃការបង់ប្រាក់ចេញពីប្រធានបទ Bookshelf នៅពេលប្រើ Fluid Checkout ។','Account password' => 'ពាក្យសម្ងាត់គណនី','An account will be created with the information provided at checkout when completing the order.' => 'គណនីមួយនឹងត្រូវបានបង្កើតជាមួយនឹងព័ត៌មានដែលបានផ្តល់ឱ្យនៅពេលចេញលុយនៅពេលបំពេញការបញ្ជាទិញ។','Choose the style of the progress bar.' => 'ជ្រើសរើសរចនាប័ទ្មនៃរបារវឌ្ឍនភាព។','Bars' => 'បារ','Theme Ireca' => 'ប្រធានបទ Ireca','WooCommerce page layout' => 'ប្លង់ទំព័រ WooCommerce','Force wide layout on WooCommerce pages' => 'បង្ខំប្លង់ធំទូលាយនៅលើទំព័រ WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'នេះធានាថាផ្នែកមាតិកាមិនតូចចង្អៀតពេកនៅលើទំព័រ WooCommerce រួមទាំងការចេញ រទេះ ការបញ្ជាទិញដែលបានទទួល ការបញ្ជាទិញបង់ប្រាក់ និងទំព័រគណនី។','WooCommerce Smart Coupons' => 'គូប៉ុងឆ្លាតវៃ WooCommerce','Position on checkout page' => 'ទីតាំងនៅលើទំព័រទូទាត់','Choose where to display the available coupons section on the checkout page.' => 'ជ្រើសរើសកន្លែងដែលត្រូវបង្ហាញផ្នែកប័ណ្ណដែលមាននៅលើទំព័រទូទាត់។','Before the progress bar' => 'មុនពេលរបារវឌ្ឍនភាព','After the progress bar' => 'បន្ទាប់ពីរបារវឌ្ឍនភាព','Before coupon codes section' => 'ផ្នែកមុនលេខកូដគូប៉ុង','Format phone numbers according to the rules for each country.' => 'ធ្វើទ្រង់ទ្រាយលេខទូរស័ព្ទដោយយោងទៅតាមច្បាប់សម្រាប់ប្រទេសនីមួយៗ។','Use precise phone number validation' => 'ប្រើការបញ្ជាក់លេខទូរស័ព្ទច្បាស់លាស់','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'នេះគឺជាមុខងារពិសោធន៍ ហើយប្រហែលជាមិនដំណើរការដូចការរំពឹងទុកក្នុងការរៀបចំទាំងអស់។ ប្រើវាដោយប្រុងប្រយ័ត្ន។','Phone number validation types used when precise validation is enabled.' => 'ប្រភេទនៃការផ្ទៀងផ្ទាត់លេខទូរស័ព្ទដែលប្រើនៅពេលដែលការផ្ទៀងផ្ទាត់ជាក់លាក់ត្រូវបានបើក។','Mobile' => 'ទូរស័ព្ទចល័ត','Fixed line' => 'បន្ទាត់ថេរ','Toll free' => 'ឥតគិតថ្លៃ','Or' => 'ឬ','Contact' => 'ទំនាក់ទំនង','Multi step' => 'ជំហានច្រើន','2 columns' => 'ជួរឈរចំនួន ២','1 column' => 'ជួរឈរ ១','Before checkout steps' => 'ជំហានមុនពេលទូទាត់ប្រាក់','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'នៅពេលប្រើប្លង់ទូទាត់ប្រាក់ <em>&quot;1 ជួរឈរ&quot;</em> ជម្រើសនេះតែងតែត្រូវបានកំណត់ទៅ <em>&quot;មុនជំហានទូទាត់ប្រាក់&quot;</em> ហើយក៏អនុវត្តចំពោះទិដ្ឋភាពផ្ទៃតុផងដែរ។','Position for the extra order summary section on mobile.' => 'ទីតាំងសម្រាប់ផ្នែកសង្ខេបការបញ្ជាទិញបន្ថែមនៅលើទូរសព្ទដៃ។','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'ជម្រើស <em>&quot;បឋមកថានៅលើគេហទំព័រ&quot;</em> អនុវត្តតែនៅពេលប្រើបឋមកថាដែលគ្មានការរំខានប៉ុណ្ណោះ។','On the site header (requires distraction-free header)' => 'នៅលើបឋមកថាគេហទំព័រ (តម្រូវឱ្យមានបឋមកថាដែលគ្មានការរំខាន)','Initial state for the expansible order summary section on mobile.' => 'ស្ថានភាពដំបូងសម្រាប់ផ្នែកសង្ខេបការបញ្ជាទិញដែលអាចពង្រីកបាននៅលើទូរសព្ទចល័ត។','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'យើងសូមណែនាំឱ្យកំណត់វាជា <em>&quot;បានពង្រីក&quot;</em> សម្រាប់ប្រទេសដូចខាងក្រោម៖ <strong>អាល្លឺម៉ង់</strong> <strong>អូទ្រីស</strong> <strong>ស្វីស</strong> <strong>ហូឡង់</strong> <strong>ប៉ូឡូញ</strong> <strong>បែលហ្ស៊ិក</strong> និង <strong>បារាំង</strong> ។','Collapsed' => 'បានបង្រួម','Expanded' => 'បានពង្រីក','Do not show' => 'កុំបង្ហាញ','yes' => 'បាទ/ចាស៎','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'វាលលេខទូរស័ព្ទដឹកជញ្ជូនអាចត្រូវបានបង្ខំឱ្យ &quot;តម្រូវឱ្យបំពេញ&quot; ប្រសិនបើផ្នែកអាសយដ្ឋានវិក្កយបត្រត្រូវបានបង្ហាញបន្ទាប់ពីផ្នែកអាសយដ្ឋានដឹកជញ្ជូន ហើយវាលលេខទូរស័ព្ទវិក្កយបត្រត្រូវបានកំណត់ជា &quot;តម្រូវឱ្យបំពេញ&quot;។ នេះគឺចាំបាច់ដើម្បីធានាថាអាសយដ្ឋានដឹកជញ្ជូនអាចត្រូវបានចម្លងទៅកាន់អាសយដ្ឋានវិក្កយបត្រនៅពេលដែលជម្រើសនោះត្រូវបានធីក បើមិនដូច្នោះទេអតិថិជនប្រហែលជាមិនអាចបំពេញទម្រង់បែបបទទូទាត់ប្រាក់បានទេ។','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'វាលលេខទូរស័ព្ទសម្រាប់ចេញវិក្កយបត្រអាចត្រូវបានបង្ខំឱ្យដាក់ជា &quot;តម្រូវឲ្យមាន&quot; ប្រសិនបើផ្នែកអាសយដ្ឋានសម្រាប់ចេញវិក្កយបត្រត្រូវបានបង្ហាញមុនផ្នែកអាសយដ្ឋានដឹកជញ្ជូន ហើយវាលលេខទូរស័ព្ទដឹកជញ្ជូនត្រូវបានកំណត់ជា &quot;តម្រូវឲ្យមាន&quot;។ នេះគឺចាំបាច់ដើម្បីធានាថាអាសយដ្ឋានដឹកជញ្ជូនអាចត្រូវបានចម្លងទៅកាន់អាសយដ្ឋានសម្រាប់ចេញវិក្កយបត្រនៅពេលដែលជម្រើសនោះត្រូវបានធីក បើមិនដូច្នោះទេ អតិថិជនប្រហែលជាមិនអាចបំពេញទម្រង់បែបបទទូទាត់ប្រាក់បានទេ។','Settings profiles' => 'ប្រវត្តិរូបការកំណត់','Settings profile' => 'ប្រវត្តិរូបការកំណត់','You do not have permission to perform this action.' => 'អ្នកមិនមានការអនុញ្ញាតឱ្យអនុវត្តសកម្មភាពនេះទេ។','You do not have permission to activate plugins.' => 'អ្នកមិនមានសិទ្ធិធ្វើឱ្យកម្មវិធីជំនួយសកម្មទេ។','Missing plugin.' => 'បាត់កម្មវិធីជំនួយ។','Plugin activated.' => 'កម្មវិធីជំនួយត្រូវបានធ្វើឱ្យសកម្ម។','The following changes will be applied:' => 'ការ​ផ្លាស់ប្ដូរ​ខាងក្រោម​នឹង​ត្រូវ​បាន​អនុវត្ត៖','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'ចាប់តាំងពី Fluid Checkout 5.0 មក ការកំណត់ត្រូវបានរក្សាទុកខុសគ្នា។ ជម្រើស Legacy នៅតែត្រូវបានរក្សាទុកក្នុងមូលដ្ឋានទិន្នន័យ ដើម្បីអនុញ្ញាតឱ្យមានការបន្ទាបទៅកំណែមុនៗ ប្រសិនបើចាំបាច់។','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'ហាងរបស់អ្នកបានដំណើរការប្រហែល 2 សប្តាហ៍លើការកំណត់ថ្មី ដូច្នេះអ្នកអាចសម្អាតជម្រើសចាស់ៗដែលរក្សាទុកក្នុងមូលដ្ឋានទិន្នន័យ។ សូមចំណាំថា បន្ទាប់ពីការសម្អាត ប្រសិនបើអ្នកត្រូវការបន្ទាបទៅកំណែមុននៃកម្មវិធីជំនួយ វានឹងប្រើតម្លៃលំនាំដើមសម្រាប់ការកំណត់ទាំងអស់។','Fluid Checkout settings cleanup' => 'ការសម្អាតការកំណត់ Fluid Checkout','Delete leftover options' => 'លុបជម្រើសដែលនៅសល់','Help us improve Fluid Checkout' => 'ជួយយើងកែលម្អការទូទាត់ប្រាក់រាវ','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'ចែករំលែករបាយការណ៍បរិស្ថានគេហទំព័រអនាមិកជាមួយ Fluid Checkout ដើម្បីទទួលបានការគាំទ្រលឿនជាងមុន និងជួយយើងកែលម្អភាពឆបគ្នា និងវាស់ស្ទង់ផលប៉ះពាល់។ មិនមានទិន្នន័យអតិថិជន អ្នកប្រើប្រាស់ ឬទិន្នន័យរសើបណាមួយត្រូវបានរួមបញ្ចូលទេ។ អ្នកអាចជ្រើសរើសអ្វីដែលត្រូវចែករំលែកនៅពេលណាក៏បានពីការកំណត់ឧបករណ៍។','Enable site environment reports' => 'បើករបាយការណ៍បរិស្ថានគេហទំព័រ','Review settings' => 'ពិនិត្យមើលការកំណត់','This preview has expired. Reload the admin page to start a new preview.' => 'ការមើលជាមុននេះផុតកំណត់ហើយ។ សូមផ្ទុកទំព័រអ្នកគ្រប់គ្រងឡើងវិញ ដើម្បីចាប់ផ្តើមការមើលជាមុនថ្មី។','Preview expired' => 'ការមើលជាមុនផុតកំណត់','Orders cannot be placed in the preview.' => 'មិនអាចធ្វើការបញ្ជាទិញនៅក្នុងការមើលជាមុនបានទេ។','Logging in is not available in the preview.' => 'ការចូលមិនអាចប្រើនៅក្នុងការមើលជាមុនបានទេ។','Accounts cannot be created in the preview.' => 'មិនអាចបង្កើតគណនីនៅក្នុងការមើលជាមុនបានទេ។','Requests to other sites are blocked in the preview.' => 'សំណើទៅកាន់គេហទំព័រផ្សេងទៀតត្រូវបានរារាំងនៅក្នុងការមើលជាមុន។','Processing…' => 'កំពុងដំណើរការ…','Something went wrong. Please try again.' => 'មានអ្វីមួយខុសប្រក្រតី។ សូមព្យាយាមម្តងទៀត។','Activate plugin' => 'ធ្វើឱ្យកម្មវិធីជំនួយសកម្ម','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - កញ្ចប់ទូទាត់ប្រាក់ពេញលេញ','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'មុខងារ PRO ទាំងអស់ + កម្មវិធីបន្ថែមទាំងអស់ តម្លៃតែមួយ។ រចនាគំរូ ទំព័ររទេះ និងទំព័រទទួលការបញ្ជាទិញដែលបានធ្វើឱ្យប្រសើរឡើង ការផ្គូផ្គងគណនី និងច្រើនទៀត។','Optimized order pay page' => 'ទំព័រទូទាត់ការបញ្ជាទិញដែលបានធ្វើឱ្យប្រសើរឡើង','Express checkout buttons from supported payment methods' => 'ប៊ូតុងទូទាត់ប្រាក់រហ័សពីវិធីបង់ប្រាក់ដែលគាំទ្រ','Delayed account creation' => 'ការបង្កើតគណនីយឺតយ៉ាវ','Address autocomplete with Google Maps APIs' => 'ការបំពេញអាសយដ្ឋានដោយស្វ័យប្រវត្តិជាមួយ Google Maps APIs','Multiple saved addresses with the address book' => 'អាសយដ្ឋានដែលបានរក្សាទុកច្រើនជាមួយសៀវភៅអាសយដ្ឋាន','EU-VAT assistant' => 'ជំនួយការ EU-VAT','Hide this section' => 'លាក់ផ្នែកនេះ','Learn more' => 'ស្វែងយល់បន្ថែម','Get early access' => 'ទទួលបានការចូលប្រើប្រាស់មុនគេ','Activate add-on' => 'ធ្វើឱ្យកម្មវិធីបន្ថែមសកម្ម','Get more out of your checkout journey' => 'ទទួលបានអត្ថប្រយោជន៍កាន់តែច្រើនពីដំណើរទូទាត់ប្រាក់របស់អ្នក','Test API key' => 'សាកល្បង​សោ API','Guided setup' => 'ការដំឡើងដែលមានការណែនាំ','Options' => 'ជម្រើស','Set up layout and design on the <a href="%s">checkout options</a>.' => 'រៀបចំប្លង់ និងការរចនានៅលើ <a href="%s">ជម្រើសទូទាត់ប្រាក់</a> ។','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'បើក​ការ​ទូទាត់​ប្រាក់​ជា​ភ្ញៀវ និង/ឬ​ពិនិត្យ​មើល <a href="%s">​ការ​កំណត់​គណនី​អតិថិជន</a> ។','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'បើកដំណើរការទំព័រ <a href="%1$s">រទេះ</a> <a href="%2$s">ទិញទំនិញ អរគុណ</a> និង <a href="%3$s">បង់ប្រាក់បញ្ជាទិញ</a> ដែលបានធ្វើឱ្យប្រសើរឡើង។','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'បើកការ <a href="%s">បំពេញអាសយដ្ឋានដោយស្វ័យប្រវត្តិ</a> ពី Google Maps។','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'បើកដំណើរការអាសយដ្ឋានដែលបានរក្សាទុកច្រើនជាមួយ <a href="%s">សៀវភៅអាសយដ្ឋាន</a> ។','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'ពិនិត្យមើលថាតើមាន <a href="%s">ជម្រើសរួមបញ្ចូល</a> ណាមួយដែលអាចប្រើបានសម្រាប់ស្បែក ឬកម្មវិធីជំនួយផ្សេងទៀតដែលអ្នកបានដំឡើងឬអត់។','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'ទទួលបានការគាំទ្រលឿនជាងមុន និងជួយយើងកែលម្អភាពឆបគ្នា និងវាស់ស្ទង់ផលប៉ះពាល់។ <a href="%s">បើកការតាមដានការប្រើប្រាស់</a> ពីការកំណត់ឧបករណ៍។','Missing settings tab.' => 'បាត់ផ្ទាំងការកំណត់។','Getting started' => 'ការចាប់ផ្តើម','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>ល្អណាស់! ទំព័រទូទាត់ប្រាក់របស់អ្នកឥឡូវនេះកំពុងដំណើរការនៅលើ Fluid Checkout។</strong> ខាងក្រោមនេះជាជំហានមួយចំនួនដើម្បីចាប់ផ្តើម៖','Completed' => 'បានបញ្ចប់','Preview report data' => 'មើលទិន្នន័យរបាយការណ៍ជាមុន','Send now' => 'ផ្ញើឥឡូវនេះ','Auto-detect' => 'រកឃើញដោយស្វ័យប្រវត្តិ','Afrikaans' => 'អាហ្វ្រិកាន','Albanian' => 'អាល់បានី','Amharic' => 'អាំហារិក','Arabic' => 'ភាសាអារ៉ាប់','Armenian' => 'អាមេនី','Azerbaijani' => 'អាស៊ែបៃហ្សង់','Basque' => 'បាស','Belarusian' => 'បេឡារុស្ស','Bengali' => 'បេងហ្គាលី','Bosnian' => 'បូស្នៀ','Bulgarian' => 'ប៊ុលហ្គារី','Burmese' => 'ភូមា','Catalan' => 'កាតាឡាន','Chinese' => 'ចិន','Chinese (Simplified)' => 'ភាសាចិន (សាមញ្ញ)','Chinese (Hong Kong)' => 'ចិន (ហុងកុង)','Chinese (Traditional)' => 'ចិន (ប្រពៃណី)','Croatian' => 'ភាសាក្រូអាត','Czech' => 'ឆែក','Danish' => 'ភាសាដាណឺម៉ាក','Dutch' => 'ហូឡង់','English' => 'អង់គ្លេស','English (Australian)' => 'អង់គ្លេស (អូស្ត្រាលី)','English (Great Britain)' => 'អង់គ្លេស (ចក្រភពអង់គ្លេស)','Estonian' => 'អេស្តូនី','Farsi' => 'ហ្វាស៊ី','Finnish' => 'ហ្វាំងឡង់','Filipino' => 'ហ្វីលីពីន','French' => 'ភាសាបារាំង','French (Canadian)' => 'បារាំង (កាណាដា)','Galician' => 'ហ្គាលីស្យា','Georgian' => 'ហ្សកហ្ស៊ី','German' => 'អាល្លឺម៉ង់','Greek' => 'ក្រិក','Gujarati' => 'គុចារ៉ាទី','Hebrew' => 'ភាសាហេព្រើរ','Hindi' => 'ហិណ្ឌូ','Hungarian' => 'ហុងគ្រី','Icelandic' => 'អ៊ីស្លង់','Indonesian' => 'ឥណ្ឌូនេស៊ី','Italian' => 'អ៊ីតាលី','Japanese' => 'ជប៉ុន','Kannada' => 'កាន់ណាដា','Kazakh' => 'កាហ្សាក់ស្ថាន','Khmer' => 'ខ្មែរ','Korean' => 'កូរ៉េ','Kyrgyz' => 'គីហ្ស៊ី','Lao' => 'ឡាវ','Latvian' => 'ឡាតវី','Lithuanian' => 'លីទុយអានី','Macedonian' => 'ម៉ាសេដូន','Malay' => 'ម៉ាឡេ','Malayalam' => 'ម៉ាឡាយ៉ាឡាម','Marathi' => 'ម៉ារ៉ាធី','Mongolian' => 'ម៉ុងហ្គោលី','Nepali' => 'នេប៉ាល់','Norwegian' => 'ន័រវេស','Polish' => 'ប៉ូឡូញ','Portuguese' => 'ព័រទុយហ្គាល់','Portuguese (Brazil)' => 'ព័រទុយហ្គាល់ (ប្រេស៊ីល)','Portuguese (Portugal)' => 'ព័រទុយហ្គាល់ (ព័រទុយហ្គាល់)','Punjabi' => 'ពុនចាប៊ី','Romanian' => 'រ៉ូម៉ានី','Russian' => 'រុស្ស៊ី','Serbian' => 'ស៊ែប៊ី','Sinhalese' => 'ស៊ីនហាលីស','Slovak' => 'ស្លូវ៉ាគី','Slovenian' => 'ស្លូវេនី','Spanish' => 'អេស្ប៉ាញ','Spanish (Latin America)' => 'អេស្ប៉ាញ (អាមេរិកឡាទីន)','Swahili' => 'ស្វាហ៊ីលី','Swedish' => 'ស៊ុយអែត','Tamil' => 'ភាសាតាមីល','Telugu' => 'ភាសាតេលូហ្គូ','Thai' => 'ថៃ','Turkish' => 'ភាសាទួរគី','Ukrainian' => 'អ៊ុយក្រែន','Urdu' => 'អ៊ូឌូរ','Vietnamese' => 'វៀតណាម','Zulu' => 'ហ្សូលូ','Google address autocomplete' => 'ការបំពេញអាសយដ្ឋាន Google ដោយស្វ័យប្រវត្តិ','Google Places API version' => 'កំណែ API របស់ Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'ជ្រើសរើសកំណែ Google Places API ដែលត្រូវប្រើ។ យើងសូមណែនាំឱ្យប្តូរទៅ Places API ថ្មីឱ្យបានឆាប់តាមដែលអាចធ្វើទៅបាន។','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'យើងសូមណែនាំឱ្យប្រើ &quot;Places API (ថ្មី)&quot; ព្រោះចាប់ពីថ្ងៃទី 1 ខែមីនា ឆ្នាំ 2025 Google នឹងផ្លាស់ទីកំណែ &quot;Places API (ចាស់)&quot; ទៅជាស្ថានភាពចាស់ មានន័យថាអ្នកនឹងមិនអាចបើកសេវាកម្មនេះសម្រាប់សោ API ថ្មីទៀតទេ ហើយកំណែ API នោះនឹងលែងមាននៅទីបំផុតទៀតហើយ។ គណនីដែលមានស្រាប់ដែលប្រើ Legacy API រួចហើយអាចបន្តដំណើរការដោយគ្មានការរំខាន។','(Recommended)' => '(បានណែនាំ)','Google API key' => 'សោ API របស់ Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'បិទភ្ជាប់សោ Google API របស់អ្នក ហើយប្រើប៊ូតុងសាកល្បងដើម្បីបញ្ជាក់ថាវាដំណើរការសម្រាប់គេហទំព័រនេះ។ ត្រូវប្រាកដថាសោនេះមានសុពលភាព និងត្រូវបានអនុញ្ញាតសម្រាប់ដែនរបស់អ្នក បើមិនដូច្នោះទេ វាលអាសយដ្ឋានអាចត្រូវបានរារាំង ដែលរារាំងអតិថិជនពីការបំពេញការបញ្ជាទិញរបស់ពួកគេ។','Enable Google address autocomplete' => 'បើកការបំពេញអាសយដ្ឋាន Google ដោយស្វ័យប្រវត្តិ','Enable address autocompletion using the Google Maps APIs.' => 'បើកការបំពេញអាសយដ្ឋានដោយស្វ័យប្រវត្តិដោយប្រើ Google Maps APIs។','Google API language' => 'ភាសា Google API','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'ភាសានេះនឹងត្រូវបានប្រើដើម្បីបង្ហាញការណែនាំអាសយដ្ឋាន Google Places API ហើយអាសយដ្ឋានក៏នឹងត្រូវបានបំពេញដោយស្វ័យប្រវត្តិជាភាសានេះផងដែរ។','Result types' => 'ប្រភេទលទ្ធផល','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ទុក​ឲ្យ​ទទេ​ដើម្បី​ទទួលយក​លទ្ធផល​ប្រភេទ​ណាមួយ ដែល​ជាធម្មតា​ផ្តល់​លទ្ធផល​ផ្គូផ្គង​កាន់តែ​ល្អ។ <a href="%s" target="_blank">សូមមើល​ឯកសារ​សម្រាប់​ព័ត៌មាន​លម្អិត​បន្ថែម</a> ។<br> ជ្រើសរើសលទ្ធផលស្វែងរកអាសយដ្ឋានរហូតដល់ 5 ប្រភេទ ដើម្បីត្រឡប់ទៅកាន់វាលបំពេញអាសយដ្ឋានដោយស្វ័យប្រវត្តិ។<br> ចូលមើលឯកសារ Google Maps ដើម្បីស្វែងយល់បន្ថែមអំពី <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ប្រភេទដែលគាំទ្រ</a> ។','Result types (Legacy API)' => 'ប្រភេទលទ្ធផល (API ចាស់)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'តើលទ្ធផលស្វែងរកអាសយដ្ឋានប្រភេទណាដែលត្រូវប្រគល់មកវិញ នៅពេលប្រើ Places API (Legacy)។<br> ចូលមើលឯកសារនៃ Legacy Google Places API ដើម្បីស្វែងយល់បន្ថែមអំពី <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">ប្រភេទដែលគាំទ្រ</a> ។','Company fields' => 'វាលក្រុមហ៊ុន','Enable autocomplete for the company name if available' => 'បើកការបំពេញដោយស្វ័យប្រវត្តិសម្រាប់ឈ្មោះក្រុមហ៊ុន ប្រសិនបើមាន','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'បើកការបំពេញដោយស្វ័យប្រវត្តិនៃវាលក្រុមហ៊ុនជាមួយនឹងព័ត៌មានឈ្មោះក្រុមហ៊ុននៅពេលប្រគល់មកវិញពី Google Maps APIs។','Business search' => 'ការស្វែងរកអាជីវកម្ម','Enable search for businesses in the company field' => 'បើកការស្វែងរកអាជីវកម្មនៅក្នុងវាលក្រុមហ៊ុន','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'បើកការណែនាំអាសយដ្ឋានដែលភ្ជាប់ជាមួយអាជីវកម្មនៅពេលវាយបញ្ចូលក្នុងវាលក្រុមហ៊ុន បន្ទាប់មកបំពេញវាលអាសយដ្ឋានទាំងអស់ដោយស្វ័យប្រវត្តិ នៅពេលដែលអាជីវកម្មត្រូវបានជ្រើសរើសពីការផ្ដល់យោបល់។','Company result types' => 'ប្រភេទលទ្ធផលរបស់ក្រុមហ៊ុន','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ជ្រើសរើសលទ្ធផលស្វែងរកអាសយដ្ឋានរហូតដល់ 5 ប្រភេទ ដើម្បីបង្ហាញនៅលើវាលក្រុមហ៊ុនដែលបំពេញដោយស្វ័យប្រវត្តិ។<br> តម្លៃដែលបានណែនាំគឺ <code>establishment</code> ដែលរួមបញ្ចូលប្រភេទអាជីវកម្មភាគច្រើន។<br> ទុក​ឲ្យ​ទទេ​ដើម្បី​ទទួលយក​លទ្ធផល​ប្រភេទ​ណាមួយ រួមទាំង​លទ្ធផល​ដែល​មិន​ទាក់ទង​នឹង​អាជីវកម្ម​ផងដែរ។<br> ចូលមើលឯកសារ Google Maps ដើម្បីស្វែងយល់បន្ថែមអំពី <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ប្រភេទដែលគាំទ្រ</a> ។','Google logo' => 'ឡូហ្គោ Google','Show text and logo "Powered by Google"' => 'បង្ហាញអត្ថបទ និងឡូហ្គោ &quot;ដំណើរការដោយ Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'នៅពេលធីករួច អត្ថបទ និងឡូហ្គោ &quot;ដំណើរការដោយ Google&quot; នឹងត្រូវបានបង្ហាញនៅផ្នែកខាងក្រោមនៃប្រអប់ផ្តល់យោបល់សម្រាប់ការបំពេញអាសយដ្ឋានដោយស្វ័យប្រវត្តិ។','Brasil API address autocomplete' => 'ការបំពេញអាសយដ្ឋាន API របស់ប្រេស៊ីលដោយស្វ័យប្រវត្តិ','Brasil API' => 'API របស់ប្រេស៊ីល','Enable Brasil API address autocomplete for CEP fields' => 'បើកការបំពេញអាសយដ្ឋាន Brasil API ដោយស្វ័យប្រវត្តិសម្រាប់វាល CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'ប្រើប្រាស់ Brasil API ដើម្បីទាញយក និងបំពេញអាសយដ្ឋានដោយស្វ័យប្រវត្តិដោយប្រើវាល CEP/លេខកូដប្រៃសណីយ៍។ ពាក់ព័ន្ធសម្រាប់តែអាសយដ្ឋានប្រេស៊ីលប៉ុណ្ណោះ។','API version' => 'កំណែ API','Choose which version of the Brasil API CEP method to use.' => 'ជ្រើសរើស​កំណែ​នៃ​វិធីសាស្ត្រ Brasil API CEP ដែល​ត្រូវ​ប្រើ។','Address book migration' => 'ការធ្វើចំណាកស្រុកសៀវភៅអាសយដ្ឋាន','WooCommerce addresses' => 'អាសយដ្ឋាន WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'ចម្លងអាសយដ្ឋានដឹកជញ្ជូន និងអាសយដ្ឋានវិក្កយបត្រដែលមានស្រាប់ពី WooCommerce ទៅក្នុងសៀវភៅអាសយដ្ឋានរបស់អតិថិជន។','Enable the address book feature' => 'បើកដំណើរការមុខងារសៀវភៅអាសយដ្ឋាន','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'អនុញ្ញាតឱ្យអតិថិជនរក្សាទុកអាសយដ្ឋានច្រើន និងកំណត់អាសយដ្ឋានលំនាំដើមដែលត្រូវប្រើសម្រាប់ការដឹកជញ្ជូន និងការគិតប្រាក់។','Address labels' => 'ស្លាកអាសយដ្ឋាន','Allow customers to add a custom label for each address' => 'អនុញ្ញាតឱ្យអតិថិជនបន្ថែមស្លាកផ្ទាល់ខ្លួនសម្រាប់អាសយដ្ឋាននីមួយៗ','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'ស្លាកអាសយដ្ឋានធ្វើឱ្យវាកាន់តែងាយស្រួលក្នុងការបែងចែករវាងអាសយដ្ឋានដែលបានរក្សាទុករបស់ពួកគេ (ឧ. &quot;ផ្ទះម៉ាក់&quot;)។ ស្លាកអាសយដ្ឋានគឺជាឯកជនសម្រាប់អតិថិជន ហើយនឹងមិនត្រូវបានបង្ហាញ ឬបោះពុម្ពនៅលើទំព័រព័ត៌មានលម្អិតនៃការបញ្ជាទិញ ឬវិក្កយបត្រឡើយ។','Display layout' => 'ប្លង់បង្ហាញ','Choose how saved addresses are displayed at checkout and on the cart.' => 'ជ្រើសរើសរបៀបដែលអាសយដ្ឋានដែលបានរក្សាទុកត្រូវបានបង្ហាញនៅពេលទូទាត់ប្រាក់ និងនៅលើរទេះ។','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'អនុវត្តនៅពេលទូទាត់ប្រាក់ និងនៅលើរទេះ។ អាសយដ្ឋានដែលបានរក្សាទុកនៅលើទំព័រគណនីតែងតែប្រើប្លង់កាត។','Address cards' => 'កាតអាសយដ្ឋាន','Address list' => 'បញ្ជីអាសយដ្ឋាន','Dropdown field' => 'វាល​ទម្លាក់​ចុះ','Address search' => 'ការស្វែងរកអាសយដ្ឋាន','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'បង្ហាញតម្រងស្វែងរកអាសយដ្ឋាននៅលើផ្នែកខាងមុខ នៅពេលដែលអតិថិជនមានអាសយដ្ឋានដែលបានរក្សាទុកយ៉ាងហោចណាស់ចំនួននេះ។','Not used when display layout is set to dropdown field.' => 'មិនត្រូវបានប្រើនៅពេលដែលប្លង់បង្ហាញត្រូវបានកំណត់ទៅជាវាលទម្លាក់ចុះទេ។','Addresses' => 'អាសយដ្ឋាន','Enable cart page optimizations to see more options' => 'បើកការបង្កើនប្រសិទ្ធភាពទំព័ររទេះដើម្បីមើលជម្រើសច្រើនទៀត','Sticky order summary' => 'សេចក្តីសង្ខេបនៃការបញ្ជាទិញស្អិត','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ជ្រើសរើសទីតាំងដែលត្រូវបង្ហាញផ្នែកលេខកូដគូប៉ុងនៅលើទំព័ររទេះ។ អនុវត្តបានតែនៅពេលដែលរទេះ AJAX ត្រូវបានបើក និងប្រសិនបើការប្រើប្រាស់លេខកូដគូប៉ុងត្រូវបានបើកនៅក្នុងការកំណត់ WooCommerce។','Layout of cross-sell' => 'ប្លង់នៃការលក់ឆ្លង','Cross-sells displayed' => 'ការលក់ឆ្លងត្រូវបានបង្ហាញ','Items' => 'វត្ថុ','Cart page optimization' => 'ការបង្កើនប្រសិទ្ធភាពទំព័ររទេះ','Give your cart the same clear, conversion-focused layout as your checkout.' => 'ផ្តល់ឱ្យរទេះរបស់អ្នកនូវប្លង់ច្បាស់លាស់ និងផ្តោតលើការបំប្លែងដូចគ្នានឹងការទូទាត់ប្រាក់របស់អ្នក។','Match the cart layout to the checkout page for a consistent purchase journey.' => 'ផ្គូផ្គងប្លង់រទេះទិញទំនិញទៅនឹងទំព័រទូទាត់ប្រាក់ ដើម្បីទទួលបានដំណើរទិញទំនិញដែលស៊ីសង្វាក់គ្នា។','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'រក្សា​ឲ្យ​រទេះ​ទំនិញ​ទាន់សម័យ​ជានិច្ច​នៅ​ផ្ទៃខាងក្រោយ ដោយ​មិន​ចាំបាច់​ផ្ទុក​ទំព័រ​ឡើងវិញ​ទាំងស្រុង​នៅពេល​បរិមាណ​ផ្លាស់ប្តូរ​។','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'ដាក់លេខកូដគូប៉ុង ការដឹកជញ្ជូន និងការលក់ឆ្លងនៅកន្លែងដែលពួកវាបម្លែងបានល្អបំផុតបំផុត។','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'រក្សា​សេចក្ដីសង្ខេប​នៃ​ការបញ្ជាទិញ​ឲ្យ​អាចមើលឃើញ​ពេល​កំពុង​រំកិល​ចុះឡើង ហើយ​បន្ថែម​និមិត្តសញ្ញា​ទុកចិត្ត​នៅកន្លែង​ដែល​អ្នកទិញ​ត្រូវការ​ការធានា​ឡើងវិញ។','Columns' => 'ជួរឈរ','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'រចនាប័ទ្មទូទៅសម្រាប់ជំហានទូទាត់ប្រាក់ សេចក្តីសង្ខេបនៃការបញ្ជាទិញ និងផ្នែកផ្សេងៗទៀត។ អនុវត្តចំពោះទំព័រទូទាត់ប្រាក់ រទេះ ទំព័រថ្លែងអំណរគុណ (បានទទួលការបញ្ជាទិញ) និងទំព័រមើលការបញ្ជាទិញផ្សេងទៀត។','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'នៅពេលប្រើប្លង់ <em>&quot;1 ជួរឈរ&quot;</em> ជាមួយគំរូរចនា <em>&quot;បំបែក&quot;</em> ជួរឈរខាងស្តាំនឹងត្រូវបានបង្ហាញលុះត្រាតែផ្ទៃធាតុក្រាហ្វិករបារចំហៀងទំព័រសកម្ម (របារចំហៀងទូទាត់ប្រាក់ របារចំហៀងរទេះ ឬរបារចំហៀងទទួលបានការបញ្ជាទិញ)។ បើមិនដូច្នោះទេ ទំព័រនឹងនៅតែជាជួរឈរតែមួយដែលមានរចនាប័ទ្មបំបែក។','Split column background' => 'ផ្ទៃខាងក្រោយបំបែកជួរឈរ','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'ជ្រើសរើសពណ៌ផ្ទៃខាងក្រោយសម្រាប់ជួរឈរបន្ទាប់បន្សំនៃការរចនាបំបែក។ ទុកឱ្យទទេដើម្បីប្រើពណ៌ផ្ទៃខាងក្រោយនៃសេចក្តីសង្ខេបនៃការបញ្ជាទិញ។','Page templates' => 'គំរូទំព័រ','Checkout template' => 'គំរូទូទាត់ប្រាក់','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'បានណែនាំសម្រាប់ការរំខានតិចជាងមុននៅពេលទូទាត់ប្រាក់។ <a href="https://baymard.com/blog/cart-abandonment" target="_blank">សូមអានការស្រាវជ្រាវអំពីការបោះបង់ចោលរទេះ</a> ។','Sticky progress bar' => 'របារវឌ្ឍនភាពស្អិត','Progress bar style' => 'រចនាប័ទ្មរបារវឌ្ឍនភាព','Order totals' => 'សរុបការបញ្ជាទិញ','Background color' => 'ពណ៌ផ្ទៃខាងក្រោយ','Action link' => 'តំណភ្ជាប់សកម្មភាព','Mobile order summary' => 'សេចក្តីសង្ខេបនៃការបញ្ជាទិញតាមទូរស័ព្ទ','Mobile initial state' => 'ស្ថានភាពដំបូងរបស់ទូរស័ព្ទចល័ត','Enable editing cart items at checkout' => 'អនុញ្ញាតឱ្យកែសម្រួលទំនិញក្នុងរទេះនៅពេលទូទាត់ប្រាក់','Allow customers to change product quantities or remove items directly at the checkout page.' => 'អនុញ្ញាតឱ្យអតិថិជនផ្លាស់ប្តូរបរិមាណផលិតផល ឬលុបទំនិញចេញដោយផ្ទាល់នៅទំព័រទូទាត់ប្រាក់។','Cart item errors' => 'កំហុសទំនិញក្នុងរទេះ','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'អនុវត្តបានលុះត្រាតែលេខកូដគូប៉ុងត្រូវបានបង្ហាញជាផ្នែកដាច់ដោយឡែកនៅលើទំព័រទូទាត់ប្រាក់ ឬទំព័ររទេះ ហើយប្រសិនបើការប្រើប្រាស់លេខកូដគូប៉ុងត្រូវបានបើកនៅក្នុងការកំណត់ WooCommerce។','Coupon codes position' => 'ទីតាំងលេខកូដគូប៉ុង','Apply coupon button' => 'ប៊ូតុងអនុវត្តប័ណ្ណបញ្ចុះតម្លៃ','Select style of the "apply coupon" button.' => 'ជ្រើសរើសរចនាប័ទ្មនៃប៊ូតុង &quot;អនុវត្តប័ណ្ណបញ្ចុះតម្លៃ&quot;។','Address line 2' => 'អាសយដ្ឋានជួរទី 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ការកំណត់នេះត្រូវបានចែករំលែករវាងផ្នែកទូទាត់ប្រាក់ និងផ្នែកទទួលក្នុងស្រុក។ នៅលើផ្នែកទទួលក្នុងស្រុក វាក៏សម្រេចថាតើឧបករណ៍ជ្រើសរើសដឹកជញ្ជូន/ទទួលបង្ហាញនៅខាងក្នុងផ្នែកវិធីដឹកជញ្ជូន (មុនអាសយដ្ឋាន) ឬជាផ្នែកដាច់ដោយឡែក (ក្រោយ)។','Customer accounts' => 'គណនីអតិថិជន','Guest checkout' => 'ការបង់ប្រាក់របស់ភ្ញៀវ','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'ជម្រើសទូទាត់ប្រាក់ជាភ្ញៀវ ការចូល និងការបង្កើតគណនីពីទំព័រការកំណត់គណនី WooCommerce។ ពួកវាត្រូវបានគ្រប់គ្រងនៅទីនេះសម្រាប់ភាពងាយស្រួលរបស់អ្នក ដូច្នេះអ្នកអាចប្រើតម្លៃផ្សេងៗគ្នាក្នុងមួយប្រវត្តិរូបការកំណត់។','Allow customers to checkout without an account' => 'អនុញ្ញាតឱ្យអតិថិជនទូទាត់ប្រាក់ដោយមិនចាំបាច់មានគណនី','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>បានណែនាំ</strong> ដើម្បីកុំឱ្យអតិថិជនត្រូវបានស្នើសុំឱ្យបង្កើតគណនី ឬចូលគណនីអំឡុងពេលទូទាត់ប្រាក់ ដែលអាចធ្វើឱ្យអត្រាបំលែងថយចុះ។','When disabled, customers must log in or create an account to complete the purchase.' => 'នៅពេលបិទដំណើរការ អតិថិជនត្រូវតែចូល ឬបង្កើតគណនីដើម្បីបញ្ចប់ការទិញ។','Login at checkout' => 'ចូលគណនីនៅពេលទូទាត់ប្រាក់','Enable log-in during checkout' => 'បើកការចូលអំឡុងពេលទូទាត់ប្រាក់','Show a link for returning customers to log in from the checkout page.' => 'បង្ហាញតំណភ្ជាប់សម្រាប់អតិថិជនដែលត្រឡប់មកវិញ ដើម្បីចូលពីទំព័រទូទាត់ប្រាក់។','Account creation' => 'ការបង្កើតគណនី','Allow customers to create an account during checkout' => 'អនុញ្ញាតឱ្យអតិថិជនបង្កើតគណនីអំឡុងពេលទូទាត់ប្រាក់','Customers can create an account before placing their order.' => 'អតិថិជនអាចបង្កើតគណនីមុនពេលធ្វើការបញ្ជាទិញ។','Allow customers to create an account from the My account page' => 'អនុញ្ញាតឱ្យអតិថិជនបង្កើតគណនីពីទំព័រគណនីរបស់ខ្ញុំ','Customers can register a new account from the My account page.' => 'អតិថិជនអាចចុះឈ្មោះគណនីថ្មីពីទំព័រគណនីរបស់ខ្ញុំ។','Username' => 'ឈ្មោះអ្នកប្រើប្រាស់','Generate from customer\'s name' => 'បង្កើតពីឈ្មោះអតិថិជន','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>បានណែនាំ</strong> ដើម្បីកុំឱ្យអតិថិជនជ្រើសរើសឈ្មោះអ្នកប្រើប្រាស់អំឡុងពេលទូទាត់ប្រាក់ ដែលអាចបន្ថយអត្រាបំលែង។','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'ឈ្មោះអ្នកប្រើប្រាស់ត្រូវបានបង្កើតចេញពីឈ្មោះអតិថិជន ឬពីអាសយដ្ឋានអ៊ីមែលនៅពេលដែលឈ្មោះមិនអាចប្រើបាន។','Password' => 'ពាក្យសម្ងាត់','Send password setup link' => 'ផ្ញើតំណដំឡើងពាក្យសម្ងាត់','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>បានណែនាំ</strong> ដើម្បីកុំឱ្យអតិថិជនត្រូវបានស្នើសុំឱ្យកំណត់ពាក្យសម្ងាត់អំឡុងពេលទូទាត់ប្រាក់ ដែលអាចបន្ថយអត្រាបំលែង។','Customers receive an email to create their password securely.' => 'អតិថិជនទទួលបានអ៊ីមែលដើម្បីបង្កើតពាក្យសម្ងាត់របស់ពួកគេដោយសុវត្ថិភាព។','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'អនុញ្ញាតឱ្យអតិថិជនដែលបានចុះឈ្មោះបញ្ចប់ការទូទាត់ប្រាក់ដោយមិនចាំបាច់ចូល ហើយភ្ជាប់ការបញ្ជាទិញជាមួយគណនីដែលមានស្រាប់របស់ពួកគេនៅពេលដែលព័ត៌មានលម្អិតទំនាក់ទំនងត្រូវគ្នា។','Existing account message' => 'សារគណនីដែលមានស្រាប់','Let customers create an account after placing their order, from the thank you page.' => 'អនុញ្ញាតឱ្យអតិថិជនបង្កើតគណនីមួយបន្ទាប់ពីធ្វើការបញ្ជាទិញរបស់ពួកគេ ពីទំព័រថ្លែងអំណរគុណ។','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'ជម្រើសនៅក្នុងផ្នែកនេះអាចប្រើបាននៅពេលដែលការទូទាត់ប្រាក់ជាភ្ញៀវ និងការផ្គូផ្គងគណនីត្រូវបានបើក។ សូមបើកមុខងារទាំងពីរខាងលើដើម្បីកំណត់រចនាសម្ព័ន្ធការបង្កើតគណនីដែលពន្យារពេល។','Enable delayed account creation' => 'បើកដំណើរការការបង្កើតគណនីដែលពន្យារពេល','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'បើកដំណើរការការបង្កើតគណនីដែលពន្យារពេល នៅពេលដែលទាំងការទូទាត់ប្រាក់ជាភ្ញៀវ និងការផ្គូផ្គងគណនីត្រូវបានបើកដំណើរការ។','Section position' => 'ទីតាំងផ្នែក','Before customer details section' => 'មុនផ្នែកព័ត៌មានលម្អិតរបស់អតិថិជន','After customer details section' => 'បន្ទាប់ពីផ្នែកព័ត៌មានលម្អិតរបស់អតិថិជន','Account creation benefits' => 'អត្ថប្រយោជន៍នៃការបង្កើតគណនី','Leaving the field empty will display the default text.' => 'ការទុកវាលនេះឱ្យនៅទទេនឹងបង្ហាញអត្ថបទលំនាំដើម។','Inline buttons' => 'ប៊ូតុង​ក្នុង​ជួរ','Required fields' => 'វាលដែលតម្រូវឲ្យបំពេញ','Enable gift message fields at checkout' => 'បើកដំណើរការវាលសារអំណោយនៅពេលទូទាត់ប្រាក់','Expanded gift message' => 'សារអំណោយដែលបានពង្រីក','Display gift message field always expanded' => 'បង្ហាញវាលសារអំណោយតែងតែត្រូវបានពង្រីក','Gift message in order details' => 'ព័ត៌មានលម្អិតអំពីការបញ្ជាទិញសារអំណោយ','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'មិនមានការរួមបញ្ចូលដែលអាចប្រើបាននៅពេលនេះនៅលើផ្នែកនេះទេ។ ជម្រើសដែលទាក់ទងនឹងកម្មវិធីជំនួយ និងស្បែកនីមួយៗនឹងបង្ហាញនៅទីនេះលុះត្រាតែកម្មវិធីជំនួយ ឬស្បែកនោះត្រូវបានធ្វើឱ្យសកម្ម។','Phone fields' => 'វាលទូរស័ព្ទ','Field visibility' => 'ភាពមើលឃើញវាល','Field position' => 'ទីតាំងវាល','Phone country code & validation' => 'លេខកូដប្រទេសទូរស័ព្ទ និងការផ្ទៀងផ្ទាត់','Country' => 'ប្រទេស','Enable country on phone fields' => 'បើកដំណើរការប្រទេសនៅលើវាលទូរស័ព្ទ','Filter countries for shipping or billing' => 'ត្រងប្រទេសសម្រាប់ការដឹកជញ្ជូន ឬការចេញវិក្កយបត្រ','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'កំណត់​ឧបករណ៍ជ្រើសរើសប្រទេសនៅលើវាលទូរស័ព្ទនីមួយៗទៅប្រទេសដែលត្រូវបានអនុញ្ញាតឱ្យដឹកជញ្ជូន ឬគិតប្រាក់នៅលើហាងរបស់អ្នក។','Validation' => 'ការផ្ទៀងផ្ទាត់','Enable simple validation based on country rules' => 'បើកការផ្ទៀងផ្ទាត់សាមញ្ញដោយផ្អែកលើច្បាប់ប្រទេស','Checks that the phone number is valid for the selected country, including country code and length.' => 'ពិនិត្យមើលថាលេខទូរស័ព្ទនេះមានសុពលភាពសម្រាប់ប្រទេសដែលបានជ្រើសរើស រួមទាំងលេខកូដប្រទេស និងប្រវែងផងដែរ។','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'សូមពិនិត្យមើលឱ្យកាន់តែតឹងរ៉ឹងថាលេខនោះជាលេខទូរស័ព្ទចល័ត ខ្សែលើតុ ឬប្រភេទផ្សេងទៀតដែលទទួលយកបានសម្រាប់ប្រទេសដែលបានជ្រើសរើស។ អាចនឹងបដិសេធលេខដែលមានសុពលភាពមួយចំនួន។','Validation types' => 'ប្រភេទនៃការផ្ទៀងផ្ទាត់','Placeholders' => 'កន្លែងដាក់','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'គ្មាន​លេខ​កូដ​អាជ្ញាប័ណ្ណ​ដើម្បី​គ្រប់គ្រង​នៅពេលនេះ​ទេ។ លេខ​កូដ​អាជ្ញាប័ណ្ណ​នឹង​បង្ហាញ​នៅទីនេះ នៅពេលដែល​កម្មវិធី​ជំនួយ ឬ​កម្មវិធី​បន្ថែម Fluid Checkout ដែល​មាន​អាជ្ញាប័ណ្ណ​សកម្ម។','Default delivery type' => 'ប្រភេទដឹកជញ្ជូនលំនាំដើម','Choose which delivery type will be selected by default.' => 'ជ្រើសរើសប្រភេទដឹកជញ្ជូនណាដែលនឹងត្រូវបានជ្រើសរើសតាមលំនាំដើម។','Shipping zone fields' => 'វាលតំបន់ដឹកជញ្ជូន','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'ជ្រើសរើស​វាល​ណា​ដែល​នឹង​ត្រូវ​បាន​បង្ហាញ​សម្រាប់​វាល​តម្រង​តំបន់​ដឹកជញ្ជូន​សម្រាប់​ការ​ទៅ​យក​ក្នុង​ស្រុក។ ទុក​ឲ្យ​នៅ​ទទេ​ដើម្បី​បង្ហាញ​ជម្រើស​ដែល​មាន​ទាំងអស់។','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'វាលទាំងនេះនឹងត្រូវបានបង្ហាញជាតម្រងសម្រាប់វិធីដឹកជញ្ជូនទៅយកក្នុងស្រុក។ វាលមួយចំនួនអាចនៅតែលេចឡើងនៅពេលទូទាត់ប្រាក់នៅពេលដែលមិនត្រូវបានជ្រើសរើសនៅទីនេះ ប្រសិនបើកម្មវិធីជំនួយដែលឆបគ្នាតម្រូវឱ្យពួកវាដំណើរការបានត្រឹមត្រូវ។','Order shipping address' => 'អាសយដ្ឋានដឹកជញ្ជូនការបញ្ជាទិញ','Order pay page optimization' => 'ការបង្កើនប្រសិទ្ធភាពទំព័របង់ប្រាក់តាមការបញ្ជាទិញ','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'ផ្តល់ឱ្យការបញ្ជាទិញដែលមិនទាន់បង់ប្រាក់នូវប្លង់ច្បាស់លាស់ និងផ្តោតលើការបម្លែងដូចគ្នានឹងការទូទាត់ប្រាក់។','Optimize the layout of the order pay page for orders pending payment.' => 'ធ្វើឱ្យប្លង់នៃទំព័របង់ប្រាក់សម្រាប់ការបញ្ជាទិញប្រសើរឡើងសម្រាប់ការទូទាត់ដែលកំពុងរង់ចាំការបញ្ជាទិញ។','Match the order pay experience to your checkout for a consistent purchase journey.' => 'ផ្គូផ្គងបទពិសោធន៍ទូទាត់ការបញ្ជាទិញទៅនឹងការទូទាត់ប្រាក់របស់អ្នក ដើម្បីទទួលបានដំណើរការទិញទំនិញដែលស៊ីសង្វាក់គ្នា។','Add trust symbols and badges where shoppers need reassurance before paying.' => 'បន្ថែមនិមិត្តសញ្ញា និងផ្លាកសញ្ញាទំនុកចិត្ត ដែលអ្នកទិញទំនិញត្រូវការការធានាឡើងវិញ មុនពេលបង់ប្រាក់។','Thank you page optimization' => 'សូមអរគុណចំពោះការបង្កើនប្រសិទ្ធភាពទំព័រ','Make the thank you page and order details clearer for customers after they buy.' => 'ធ្វើឱ្យទំព័រថ្លែងអំណរគុណ និងព័ត៌មានលម្អិតអំពីការបញ្ជាទិញកាន់តែច្បាស់សម្រាប់អតិថិជនបន្ទាប់ពីពួកគេទិញ។','Optimize the thank you page and account order details with a clearer layout.' => 'បង្កើនប្រសិទ្ធភាពទំព័រថ្លែងអំណរគុណ និងព័ត៌មានលម្អិតនៃការបញ្ជាទិញគណនីជាមួយនឹងប្លង់ដែលច្បាស់លាស់ជាង។','Show order status progress, actions, downloads, and notes where they make sense.' => 'បង្ហាញវឌ្ឍនភាពនៃស្ថានភាពបញ្ជាទិញ សកម្មភាព ការទាញយក និងកំណត់ចំណាំនៅកន្លែងដែលវាសមហេតុផល។','Customize order details sections on email notifications.' => 'ប្ដូរផ្នែកព័ត៌មានលម្អិតនៃការបញ្ជាទិញតាមបំណងនៅលើការជូនដំណឹងតាមអ៊ីមែល។','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'បន្ថែមនិមិត្តសញ្ញា និងផ្លាកសញ្ញាទំនុកចិត្ត ដែលអ្នកទិញត្រូវការការធានាឡើងវិញ បន្ទាប់ពីទិញរួច។','Email notifications' => 'ការជូនដំណឹងតាមអ៊ីមែល','Enable thank you page and order details optimizations to see more options' => 'បើកការបង្កើនប្រសិទ្ធភាពទំព័រថ្លែងអំណរគុណ និងព័ត៌មានលម្អិតនៃការបញ្ជាទិញ ដើម្បីមើលជម្រើសជាច្រើនទៀត','Use wide layout on thank you page' => 'ប្រើប្លង់ធំទូលាយនៅលើទំព័រថ្លែងអំណរគុណ','These options affect the thank you page, view order details on account pages and on email notifications.' => 'ជម្រើសទាំងនេះប៉ះពាល់ដល់ទំព័រថ្លែងអំណរគុណ មើលព័ត៌មានលម្អិតនៃការបញ្ជាទិញនៅលើទំព័រគណនី និងនៅលើការជូនដំណឹងតាមអ៊ីមែល។','Save settings' => 'រក្សាទុកការកំណត់','Docs' => 'ឯកសារ','Cart' => 'រទេះ','Thank you' => 'អរគុណ','Address autocomplete' => 'ការបំពេញអាសយដ្ឋានដោយស្វ័យប្រវត្តិ','Trust badges' => 'ផ្លាកសញ្ញាទំនុកចិត្ត','You do not have permission to save these settings.' => 'អ្នកមិនមានសិទ្ធិរក្សាទុកការកំណត់ទាំងនេះទេ។','Invalid save request.' => 'សំណើ​រក្សាទុក​មិន​ត្រឹមត្រូវ។','Your settings have been saved.' => 'ការកំណត់របស់អ្នកត្រូវបានរក្សាទុកហើយ។','Saving...' => 'កំពុងរក្សាទុក...','Settings could not be saved. Please try again.' => 'មិនអាចរក្សាទុកការកំណត់បានទេ។ សូមព្យាយាមម្តងទៀត។','Dismiss notice' => 'បដិសេធការជូនដំណឹង','Open settings menu' => 'បើកម៉ឺនុយការកំណត់','Close settings menu' => 'បិទម៉ឺនុយការកំណត់','Preview' => 'មើលជាមុន','Expand preview' => 'ពង្រីកការមើលជាមុន','Collapse preview' => 'បង្រួមការមើលជាមុន','Show header and footer' => 'បង្ហាញបឋមកថា និងបាតកថា','Hide header and footer' => 'លាក់បឋមកថា និងបាតកថា','Page preview' => 'ការមើលជាមុននៃទំព័រ','Preview viewport' => 'មើល​ច្រក​មើល​ជាមុន','Tablet' => 'ថេប្លេត','Desktop' => 'កុំព្យូទ័រលើតុ','Preview width' => 'ទទឹងមើលជាមុន','Decrease width' => 'បន្ថយទទឹង','Preview width in pixels' => 'ទទឹងមើលជាមុនជាភីកសែល','Increase width' => 'បង្កើនទទឹង','Preview as' => 'មើលជាមុនជា','Guest' => 'ភ្ញៀវ','Logged in' => 'បានចូល','Preview page' => 'មើលទំព័រជាមុន','Expand preview for a closer look' => 'ពង្រីកការមើលជាមុនសម្រាប់មើលឱ្យកាន់តែច្បាស់','Available with %s.' => 'មានជាមួយ %s។','Turn them on' => 'បើកពួកវា','Optimizations for this page are turned off. %s to preview the page.' => 'ការបង្កើនប្រសិទ្ធភាពសម្រាប់ទំព័រនេះត្រូវបានបិទ។ %s ដើម្បីមើលទំព័រជាមុន។','%s preview' => 'ការមើលជាមុន %s','Isolated session · nothing is saved' => 'វគ្គដាច់ដោយឡែក · គ្មានអ្វីត្រូវបានរក្សាទុកទេ','Usage tracking' => 'ការតាមដានការប្រើប្រាស់','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'ផ្ញើរបាយការណ៍បរិស្ថានគេហទំព័រដែលមិនងាយរងគ្រោះ ដើម្បីជួយ Fluid Checkout ឲ្យប្រសើរឡើងនូវភាពឆបគ្នា។ របាយការណ៍មិនត្រូវបានផ្ញើទេ រហូតដល់បើកដំណើរការនៅក្នុងជម្រើសខាងក្រោម។','Send usage tracking reports to Fluid Checkout' => 'ផ្ញើរបាយការណ៍តាមដានការប្រើប្រាស់ទៅ Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'របាយការណ៍ទាំងនេះជួយយើងកែលម្អភាពឆបគ្នា និងការគាំទ្រសម្រាប់គេហទំព័ររបស់អ្នក ហើយត្រូវបានផ្ញើជារៀងរាល់សប្តាហ៍នៅពេលបើកដំណើរការ។','No customer, admin user, or any other sensitive data is included in the reports.' => 'គ្មានអតិថិជន អ្នកប្រើប្រាស់ជាអ្នកគ្រប់គ្រង ឬទិន្នន័យរសើបផ្សេងទៀតត្រូវបានរួមបញ្ចូលនៅក្នុងរបាយការណ៍នោះទេ។','Basic environment info' => 'ព័ត៌មានបរិស្ថានមូលដ្ឋាន','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'ទិន្នន័យបញ្ជី WordPress, PHP, WooCommerce, ស្បែក និងកម្មវិធីជំនួយ។ តែងតែរួមបញ្ចូលនៅពេលដែលការរាយការណ៍ត្រូវបានបើក។ ជួយយើងឱ្យយល់ពីបរិយាកាសដែលគេហទំព័ររបស់អ្នកកំពុងដំណើរការ។','Plugin settings' => 'ការកំណត់កម្មវិធីជំនួយ','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'ផ្ញើការកំណត់កម្មវិធីជំនួយ Fluid Checkout ដើម្បីជួយជាមួយសំណើសុំជំនួយ និងជួយយើងឱ្យយល់ពីរបៀបដែលអ្នកកំពុងប្រើប្រាស់កម្មវិធីជំនួយរបស់យើង។','Coming soon' => 'ឆាប់ៗនេះ','Sales metrics' => 'រង្វាស់​ការលក់','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'ចំនួនការបញ្ជាទិញប្រចាំខែ និងការលក់សរុបសម្រាប់មួយឆ្នាំមុនពេលដំឡើង Fluid Checkout រហូតដល់ថ្ងៃនេះ។ ជួយយើងឱ្យយល់ថាតើអ្នកកំពុងរកលុយបានច្រើនជាមួយនឹងកម្មវិធីជំនួយរបស់យើងដែលបានដំឡើងឬអត់។ គ្មានទិន្នន័យអតិថិជន ឬអ្នកប្រើប្រាស់ត្រូវបានផ្ញើឡើយ។','Utilities' => 'សេវាប្រើប្រាស់','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'ប្រើសមាសភាគបញ្ជីទម្លាក់ចុះ <code>TomSelect</code> ជំនួសឱ្យ <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect គឺជាសមាសធាតុជ្រើសរើសទម្លាក់ចុះដ៏សាមញ្ញជាង ដែលងាយនឹងកើតមានកំហុសតិចជាង Select2 ខណៈពេលដែលផ្តល់មុខងារដូចគ្នា។','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'កំណត់ទំហំពុម្ពអក្សរនៅក្នុងវាលទម្រង់ទៅ 16px នៅលើទំព័រដែលបានធ្វើឱ្យប្រសើរដោយកម្មវិធីជំនួយនេះ ដើម្បីជៀសវាងការពង្រីកដោយស្វ័យប្រវត្តិនៅពេលធ្វើអន្តរកម្មជាមួយវាលទម្រង់នៅលើឧបករណ៍តូចៗ។','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari និងកម្មវិធីរុករកផ្សេងទៀតអាចនឹងពង្រីកដោយស្វ័យប្រវត្តិនៅលើឧបករណ៍ចល័ត ដើម្បីធ្វើឱ្យអក្សរងាយស្រួលអានជាងមុន នៅពេលដែលទំហំពុម្ពអក្សរតូចជាង 16px។','Enable script processing tracking on the browser console.' => 'បើកដំណើរការការតាមដានដំណើរការស្គ្រីបនៅលើកុងសូលកម្មវិធីរុករក។','Unminified assets' => 'ទ្រព្យសកម្មដែលមិនបានបង្រួម','Google Maps scripts' => 'ស្គ្រីប Google Maps','Do not remove duplicate Google Maps scripts' => 'កុំលុបស្គ្រីប Google Maps ស្ទួនចេញ','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'នៅពេលបើកដំណើរការ ស្គ្រីប Google Maps ស្ទួននឹងមិនត្រូវបានដកចេញទេ ដែលអាចបណ្តាលឱ្យមានកំហុស និងបញ្ហាដំណើរការ។ ប្រើជម្រើសនេះតែពេលកំពុងដោះស្រាយបញ្ហាប៉ុណ្ណោះ។','Widget areas' => 'តំបន់​ធាតុ​ក្រាហ្វិក','Last step on mobile' => 'ជំហានចុងក្រោយនៅលើទូរស័ព្ទចល័ត','Display widgets only at last step on mobile' => 'បង្ហាញ​ធាតុក្រាហ្វិក​តែ​នៅ​ជំហាន​ចុងក្រោយ​លើ​ទូរសព្ទ​ប៉ុណ្ណោះ','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'បង្ហាញធាតុក្រាហ្វិកសញ្ញាទុកចិត្តសម្រាប់ការទូទាត់ប្រាក់ តែនៅពេលមើលជំហានទូទាត់ប្រាក់ចុងក្រោយនៅលើឧបករណ៍ចល័តប៉ុណ្ណោះ','Standard' => 'ស្តង់ដារ','VAT number field' => 'វាលលេខអាករលើតម្លៃបន្ថែម','Add a VAT number field to the billing form.' => 'បន្ថែមវាលលេខអាករលើតម្លៃបន្ថែមទៅក្នុងទម្រង់បែបបទគិតប្រាក់។','Field label' => 'ស្លាក​វាល','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'កំណត់ស្លាកសម្រាប់វាលលេខអាករលើតម្លៃបន្ថែម (ឧ. លេខអាករលើតម្លៃបន្ថែម)។ នៅលើគេហទំព័រពហុភាសា វាជាការប្រសើរក្នុងការទុកវាលនេះឱ្យនៅទទេ ហើយបកប្រែឃ្លាដើម។','VAT Number' => 'លេខអាករលើតម្លៃបន្ថែម','EU-VAT' => 'ពន្ធលើតម្លៃបន្ថែមរបស់សហភាពអឺរ៉ុប','Enable the VAT number field to see more options' => 'បើក​វាល​លេខ​អាករ​លើ​តម្លៃ​បន្ថែម ដើម្បី​មើល​ជម្រើស​បន្ថែម​ទៀត','VAT validation' => 'ការផ្ទៀងផ្ទាត់អាករលើតម្លៃបន្ថែម','Validate VAT number field for EU-VAT during checkout' => 'ផ្ទៀងផ្ទាត់​វាល​លេខ​អាករ​លើ​តម្លៃ​បន្ថែម​សម្រាប់ EU-VAT អំឡុងពេល​ទូទាត់​ប្រាក់','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'ពិនិត្យមើលថាតើលេខអាករលើតម្លៃបន្ថែម (VAT) ដែលបានផ្តល់គឺជាលេខអាករលើតម្លៃបន្ថែមដែលមានសុពលភាពដែលបានចុះបញ្ជីនៅលើមូលដ្ឋានទិន្នន័យ VIES អឺរ៉ុប (ប្រព័ន្ធផ្លាស់ប្តូរព័ត៌មានអាករលើតម្លៃបន្ថែម)។','Shop VAT number' => 'លេខអាករលើតម្លៃបន្ថែមសម្រាប់ហាង','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'លេខអាករលើតម្លៃបន្ថែមរបស់ហាងដែលប្រើសម្រាប់ស្នើសុំការផ្ទៀងផ្ទាត់ EU-VAT និងបោះពុម្ពលើវិក្កយបត្រ។<br> <strong>យើងសូមណែនាំយ៉ាងមុតមាំឱ្យបន្ថែមលេខអាករលើតម្លៃបន្ថែមលើតម្លៃហាងរបស់អ្នក</strong> បើមិនដូច្នោះទេលទ្ធផលនៃការពិគ្រោះយោបល់ VIES អាចមិនមានសុពលភាពសម្រាប់គោលបំណងគណនេយ្យទេ។<br> ឧ។៖ <code>ATU99999999</code> ឬ <code>EE999999999</code> ។','Reverse charge' => 'បន្ទុកបញ្ច្រាស','Apply reverse charge mechanism' => 'អនុវត្តយន្តការសាកថ្មបញ្ច្រាស','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'កំណត់អត្រាពន្ធទៅសូន្យ ហើយបង្ហាញ &quot;ការគិតថ្លៃបញ្ច្រាស&quot; នៅលើវិក្កយបត្រនៅពេលដែលលេខអាករលើតម្លៃបន្ថែមរបស់អតិថិជនមានសុពលភាព។ អក្សរ &quot;ការគិតថ្លៃបញ្ច្រាស&quot; ខុសគ្នាអាចត្រូវបានទាមទារអាស្រ័យលើប្រទេសរបស់ហាង។','Same country' => 'ប្រទេសដូចគ្នា','Apply reverse charge mechanism for transactions in the shop country:' => 'អនុវត្តយន្តការគិតថ្លៃបញ្ច្រាសសម្រាប់ប្រតិបត្តិការនៅក្នុងប្រទេសហាង៖','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'អនុញ្ញាតឱ្យអនុវត្តយន្តការគិតថ្លៃបញ្ច្រាសសម្រាប់ប្រតិបត្តិការរវាងក្រុមហ៊ុននៅក្នុងប្រទេសដូចគ្នានឹងហាង។','Reverse charge exceptions' => 'ករណីលើកលែងការគិតថ្លៃបញ្ច្រាស','Select additional countries to skip applying the reverse charge mechanism.' => 'ជ្រើសរើសប្រទេសបន្ថែមដើម្បីរំលងការអនុវត្តយន្តការគិតថ្លៃបញ្ច្រាស។','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'ពន្ធនឹងត្រូវបានគិតប្រាក់លើការបញ្ជាទិញពីប្រទេសទាំងនេះ ទោះបីជាមានការផ្តល់លេខអាករលើតម្លៃបន្ថែមដែលមានសុពលភាពក៏ដោយ។','Reverse charge label on invoices' => 'ស្លាក​គិតថ្លៃ​បញ្ច្រាស​លើ​វិក្កយបត្រ','Set the label of "reverse charge" on the checkout page and order details.' => 'កំណត់ស្លាក &quot;ការគិតថ្លៃបញ្ច្រាស&quot; នៅលើទំព័រទូទាត់ប្រាក់ និងព័ត៌មានលម្អិតនៃការបញ្ជាទិញ។','Reverse charge text on invoices' => 'អត្ថបទ​គិតថ្លៃ​បញ្ច្រាស​លើ​វិក្កយបត្រ','Set the label of "reverse charge" text on invoices.' => 'កំណត់ស្លាកអក្សរ &quot;ការគិតថ្លៃបញ្ច្រាស&quot; នៅលើវិក្កយបត្រ។','Tax to be paid on reverse charge basis' => 'ពន្ធត្រូវបង់តាមមូលដ្ឋានគិតថ្លៃបញ្ច្រាស','Company name' => 'ឈ្មោះក្រុមហ៊ុន','Autocomplete company name from VAT number' => 'បំពេញឈ្មោះក្រុមហ៊ុនដោយស្វ័យប្រវត្តិពីលេខអាករលើតម្លៃបន្ថែម','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'បំពេញឈ្មោះក្រុមហ៊ុនគិតលុយដោយផ្អែកលើលេខអាករលើតម្លៃបន្ថែមដែលមានសុពលភាពដែលផ្តល់ដោយអតិថិជន។','Company name editing' => 'ការកែសម្រួលឈ្មោះក្រុមហ៊ុន','Allow editing of auto-filled company name' => 'អនុញ្ញាតឱ្យកែសម្រួលឈ្មោះក្រុមហ៊ុនដែលបំពេញដោយស្វ័យប្រវត្តិ','When enabled, customers can change the company name associated with the provided VAT number.' => 'នៅពេលបើកដំណើរការ អតិថិជនអាចផ្លាស់ប្តូរឈ្មោះក្រុមហ៊ុនដែលភ្ជាប់ជាមួយលេខអាករលើតម្លៃបន្ថែមដែលបានផ្តល់ជូន។','EU-VAT for digital goods' => 'ពន្ធលើតម្លៃបន្ថែម EU សម្រាប់ទំនិញឌីជីថល','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'ចាប់ពីថ្ងៃទី 1 ខែមករា ឆ្នាំ 2015 ការកែប្រែត្រូវបានធ្វើឡើងចំពោះបទប្បញ្ញត្តិពន្ធលើតម្លៃបន្ថែមរបស់សហភាពអឺរ៉ុបទាក់ទងនឹងទំនិញឌីជីថល ដែលប៉ះពាល់តែប្រតិបត្តិការ B2C ប៉ុណ្ណោះ។ ពន្ធលើតម្លៃបន្ថែមលើទំនិញឌីជីថលត្រូវតែគណនាដោយផ្អែកលើទីតាំងរបស់អតិថិជន ហើយភស្តុតាងនៃរឿងនេះត្រូវប្រមូល (អាសយដ្ឋាន IP និងអាសយដ្ឋានវិក្កយបត្រ)។','Tax classes for digital goods' => 'ថ្នាក់ពន្ធសម្រាប់ទំនិញឌីជីថល','Select some tax classes' => 'ជ្រើសរើសថ្នាក់ពន្ធមួយចំនួន','Location evidence' => 'ភស្តុតាងទីតាំង','Collect customer\'s location evidence' => 'ប្រមូលភស្តុតាងទីតាំងរបស់អតិថិជន','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'រក្សាទុកអាសយដ្ឋាន IP ហើយផ្ទៀងផ្ទាត់វាទល់នឹងអាសយដ្ឋានគិតលុយរបស់អតិថិជន។ អតិថិជនត្រូវតែបញ្ជាក់អាសយដ្ឋានគិតលុយរបស់ពួកគេដោយធីកប្រអប់ធីកនៅលើទំព័រទូទាត់ប្រាក់ ប្រសិនបើប្រទេសពីអាសយដ្ឋានគិតលុយ និង IP របស់ពួកគេមិនត្រូវគ្នា។','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'ជម្រើសនេះត្រូវបានគ្រប់គ្រងនៅក្នុង Fluid Checkout។ <a href="%s">ផ្លាស់ប្តូរវានៅក្នុងការកំណត់គណនីអតិថិជន</a> ។','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'ជម្រើសនេះត្រូវបានគ្រប់គ្រងនៅក្នុង Fluid Checkout។ ផ្លាស់ប្តូរវានៅក្រោម Fluid Checkout &gt; គណនីអតិថិជន។','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'ជម្រើសនេះត្រូវបានគ្រប់គ្រងនៅក្នុង Fluid Checkout។ គោលដៅដឹកជញ្ជូនត្រូវបានកំណត់ជានិច្ចទៅជា &quot;អាសយដ្ឋានដឹកជញ្ជូនលំនាំដើមរបស់អតិថិជន&quot; នៅពេលដែល Fluid Checkout ត្រូវបានធ្វើឱ្យសកម្ម។ អតិថិជននៅតែអាចផ្តល់អាសយដ្ឋានដឹកជញ្ជូន និងអាសយដ្ឋានគិតប្រាក់ផ្សេងៗគ្នាក្នុងអំឡុងពេលទូទាត់ប្រាក់។<br><br> ជម្រើសសម្រាប់កំណត់អាសយដ្ឋានវិក្កយបត្រលំនាំដើមឱ្យដូចគ្នានឹងអាសយដ្ឋានដឹកជញ្ជូនអាចរកបាននៅក្នុង <a href="%s">ការកំណត់ Fluid Checkout</a> ។','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'ជម្រើសនេះត្រូវបានគ្រប់គ្រងនៅក្នុង Fluid Checkout។ គោលដៅដឹកជញ្ជូនត្រូវបានកំណត់ជានិច្ចទៅជា &quot;អាសយដ្ឋានដឹកជញ្ជូនលំនាំដើមរបស់អតិថិជន&quot; នៅពេលដែល Fluid Checkout ត្រូវបានធ្វើឱ្យសកម្ម។ អតិថិជននៅតែអាចផ្តល់អាសយដ្ឋានដឹកជញ្ជូន និងអាសយដ្ឋានគិតប្រាក់ផ្សេងៗគ្នាក្នុងអំឡុងពេលទូទាត់ប្រាក់។<br><br> ជម្រើសសម្រាប់ការកំណត់អាសយដ្ឋានវិក្កយបត្រលំនាំដើមឱ្យដូចគ្នានឹងអាសយដ្ឋានដឹកជញ្ជូនអាចរកបាននៅ WooCommerce &gt; ការកំណត់ &gt; Fluid Checkout។','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'ការកំណត់ទាំងនេះត្រូវបានផ្លាស់ទីទៅ WP Admin &gt; Fluid Checkout &gt; Settings។','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'ផ្ទាំងការកំណត់ WooCommerce នេះត្រូវបានបញ្ឈប់ ហើយនឹងត្រូវបានដកចេញនៅក្នុង Fluid Checkout 6.0។','Go to settings page' => 'ចូលទៅកាន់ទំព័រការកំណត់','Hide this tab permanently' => 'លាក់ផ្ទាំងនេះជាអចិន្ត្រៃយ៍','Site report preview' => 'ការមើលជាមុននៃរបាយការណ៍គេហទំព័រ','This is the data that would be included in the next site environment report based on your current settings.' => 'នេះ​ជា​ទិន្នន័យ​ដែល​នឹង​ត្រូវ​បាន​រួម​បញ្ចូល​នៅ​ក្នុង​របាយការណ៍​បរិស្ថាន​គេហទំព័រ​បន្ទាប់​ដោយ​ផ្អែក​លើ​ការ​កំណត់​បច្ចុប្បន្ន​របស់​អ្នក។','Loading report preview...' => 'កំពុងផ្ទុកការមើលជាមុននៃរបាយការណ៍...','Could not load the site report preview. Try again.' => 'មិនអាចផ្ទុកការមើលជាមុននៃរបាយការណ៍គេហទំព័របានទេ។ សូមព្យាយាមម្តងទៀត។','Could not send the site report. Try again.' => 'មិនអាចផ្ញើរបាយការណ៍គេហទំព័របានទេ។ សូមព្យាយាមម្តងទៀត។','Site report sent successfully.' => 'បានផ្ញើរបាយការណ៍គេហទំព័រដោយជោគជ័យ។','Enable and send now' => 'បើក និងផ្ញើឥឡូវនេះ','Close' => 'បិទ','A site report request is already in progress. Try again in a moment.' => 'សំណើសុំរបាយការណ៍គេហទំព័រកំពុងដំណើរការរួចហើយ។ សូមព្យាយាមម្តងទៀតនៅពេលបន្តិចទៀត។','Site environment reporting is disabled.' => 'ការរាយការណ៍បរិស្ថានគេហទំព័រត្រូវបានបិទ។','No site report data is available to send.' => 'គ្មានទិន្នន័យរបាយការណ៍គេហទំព័រដែលអាចផ្ញើបានទេ។','This site domain cannot send environment reports (local or development domains are excluded).' => 'ដែនគេហទំព័រនេះមិនអាចផ្ញើរបាយការណ៍បរិស្ថានបានទេ (ដែនក្នុងស្រុក ឬដែនអភិវឌ្ឍន៍ត្រូវបានដកចេញ)។','A site report was sent recently. Try again later.' => 'របាយការណ៍គេហទំព័រមួយត្រូវបានផ្ញើថ្មីៗនេះ។ សូមព្យាយាមម្តងទៀតនៅពេលក្រោយ។','The site report could not be sent. Try again later.' => 'មិនអាចផ្ញើរបាយការណ៍គេហទំព័របានទេ។ សូមព្យាយាមម្តងទៀតនៅពេលក្រោយ។','Site environment reporting is not available.' => 'ការរាយការណ៍អំពីបរិស្ថានគេហទំព័រមិនមានទេ។','No site report data is available for the selected settings.' => 'មិនមានទិន្នន័យរបាយការណ៍គេហទំព័រសម្រាប់ការកំណត់ដែលបានជ្រើសរើសទេ។','You are not allowed to manage site reports.' => 'អ្នកមិនត្រូវបានអនុញ្ញាតឱ្យគ្រប់គ្រងរបាយការណ៍គេហទំព័រទេ។','PRO feature' => 'មុខងារ PRO','Other plugins' => 'កម្មវិធីជំនួយផ្សេងទៀត','Get only this add-on &mdash; %s' => 'ទទួលបានតែកម្មវិធីបន្ថែមនេះ — %s','Install add-on' => 'ដំឡើងកម្មវិធីបន្ថែម','Upgrade to PRO &mdash; %s' => 'ធ្វើឱ្យប្រសើរឡើងទៅ PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">ទទួលបាន %2$s</a> ដើម្បីដោះសោជម្រើសទាំងនេះ។','Add-on' => 'កម្មវិធីបន្ថែម','View documentation' => 'មើលឯកសារ','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'សំណើ​ទាមទារ​ឲ្យ​មាន​អ្នក​ប្រើប្រាស់ WordPress ដែល​បាន​ចូល។ លុប user_id ដើម្បី​ប្រើ​ទិន្នន័យ​របស់​អ្នក​ប្រើប្រាស់​បច្ចុប្បន្ន ឬ​បញ្ជូន user_id ដើម្បី​កំណត់​គោលដៅ​គណនី​ផ្សេង​ទៀត នៅ​ពេល​ដែល​អ្នក​ហៅ​អាច​កែសម្រួល​អ្នក​ប្រើប្រាស់​នោះ (សមត្ថភាព edit_user)។ សំណើ​ដែល​មិន​បាន​ផ្ទៀងផ្ទាត់​ត្រឡប់ fc_api_forbidden។ user_id ដែល​មិន​ត្រឹមត្រូវ​ត្រឡប់ fc_api_user_not_found។','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 ជាមួយ { &quot;data&quot;: { ... } } នៅពេលដែល handler ប្រគល់ payload ។','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 ជាមួយ { &quot;success&quot;: true } នៅពេលដែលមិនមាន payload (ឧទាហរណ៍ DELETE)។','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'ការបរាជ័យ​បង្ហាញ​កំហុស WordPress REST JSON ពី WP_Error (កូដ, សារ, data.status)។ កូដ​ខ្សែ​ប្រើ​បុព្វបទ fc_api_*។','Forbidden access.' => 'ហាមឃាត់ការចូល។','Target user was not found.' => 'រកមិនឃើញអ្នកប្រើប្រាស់គោលដៅទេ។','This feature is not available.' => 'មុខងារនេះមិនអាចប្រើបានទេ។','A required address field is missing.' => 'វាលអាសយដ្ឋានដែលតម្រូវឲ្យបំពេញបាត់។','Postcode or ZIP is invalid.' => 'លេខកូដប្រៃសណីយ៍ ឬលេខកូដប្រៃសណីយ៍មិនត្រឹមត្រូវ។','Phone number is invalid.' => 'លេខទូរស័ព្ទមិនត្រឹមត្រូវ។','State or county is invalid.' => 'រដ្ឋ ឬ​ស្រុក​មិន​ត្រឹមត្រូវ។','Country is invalid or has no address fields.' => 'ប្រទេសមិនត្រឹមត្រូវ ឬគ្មានវាលអាសយដ្ឋាន។','The request could not be processed.' => 'សំណើនេះមិនអាចដំណើរការបានទេ។','Back to previous step' => 'ត្រឡប់ទៅជំហានមុនវិញ','Skip to settings' => 'រំលងទៅការកំណត់','Start over and return to the first guided setup step' => 'ចាប់ផ្តើមឡើងវិញ ហើយត្រឡប់ទៅជំហានដំឡើងដែលមានការណែនាំដំបូង','Start over' => 'ចាប់ផ្តើមឡើងវិញ','Please complete all sub-steps before continuing.' => 'សូមបំពេញជំហានរងទាំងអស់មុនពេលបន្ត។','Expand' => 'ពង្រីក','Collapse' => 'បង្រួម','Skip' => 'រំលង','Mark as complete' => 'សម្គាល់ថារួចរាល់','Mark as incomplete' => 'សម្គាល់ថាមិនទាន់បានបញ្ចប់','View full-size image: %s' => 'មើលរូបភាពទំហំពេញ៖ %s','Full-size setup guide image' => 'រូបភាពណែនាំអំពីការដំឡើងទំហំពេញ','Close image' => 'បិទរូបភាព','Fluid Checkout Guided Setup' => 'ការរៀបចំដែលមានការណែនាំអំពីការទូទាត់ប្រាក់រាវ','Welcome' => 'សូមស្វាគមន៍','Explore your checkout' => 'ស្វែងយល់ពីការទូទាត់ប្រាក់របស់អ្នក','All set' => 'រួចរាល់ហើយ','You do not have permission to access this page.' => 'អ្នកមិនមានសិទ្ធិចូលប្រើទំព័រនេះទេ។','Go to step %1$d: %2$s' => 'ចូលទៅកាន់ជំហាន %1$d៖ %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'ការរៀបចំដែលមានការណែនាំនេះជួយអ្នកឱ្យស៊ាំជាមួយ Fluid Checkout។ ជំហានខាងក្រោមគឺជាកន្លែងដាក់សម្រាប់ពេលនេះ។','Continue to the next step when you are ready.' => 'បន្តទៅជំហានបន្ទាប់នៅពេលអ្នករួចរាល់។','Open your store checkout to see Fluid Checkout in action.' => 'បើកការទូទាត់ប្រាក់នៅហាងរបស់អ្នក ដើម្បីមើលដំណើរការនៃការទូទាត់ប្រាក់តាមសារធាតុរាវ។','View checkout page' => 'មើលទំព័រទូទាត់ប្រាក់','You can return to Fluid Checkout settings to continue configuring your store.' => 'អ្នកអាចត្រឡប់ទៅការកំណត់ Fluid Checkout ដើម្បីបន្តកំណត់រចនាសម្ព័ន្ធហាងរបស់អ្នក។','Review checkout and cart settings' => 'ពិនិត្យមើលការកំណត់ការទូទាត់ប្រាក់ និងរទេះ','Explore add-ons from the dashboard' => 'ស្វែងយល់ពីកម្មវិធីបន្ថែមពីផ្ទាំងគ្រប់គ្រង','Finish & go to settings' => 'បញ្ចប់ ហើយចូលទៅកាន់ការកំណត់','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'ធ្វើបច្ចុប្បន្នភាពជម្រើសភាពមើលឃើញនៃវាលទូរស័ព្ទសម្រាប់ចេញវិក្កយបត្រពីតម្លៃចាស់ ដើម្បីឲ្យត្រូវនឹងអនុសញ្ញា WooCommerce។','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'ធ្វើបច្ចុប្បន្នភាពជម្រើសភាពមើលឃើញនៃវាលទូរស័ព្ទដឹកជញ្ជូនពីតម្លៃចាស់ ដើម្បីឲ្យត្រូវនឹងអនុសញ្ញា WooCommerce។','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ចម្លងការកំណត់ពណ៌ផ្ទៃខាងក្រោយនៃសេចក្តីសង្ខេបនៃការបញ្ជាទិញទៅជម្រើសពណ៌ផ្ទៃខាងក្រោយជួរឈរបន្ទាប់បន្សំថ្មីនៃការរចនាបំបែក។','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'មុខងារជ្រើសរើសវាលដែលបានធ្វើឱ្យប្រសើរឡើងត្រូវបានបិទជានិច្ចនៅពេលប្រើកម្មវិធីជំនួយ Biteship។','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ទីតាំងបញ្ជាទិញត្រូវបានកំណត់ទៅ &quot;នៅខាងក្រោមសេចក្តីសង្ខេបនៃការបញ្ជាទិញ&quot; ជានិច្ចនៅពេលប្រើ German Market។ កម្មវិធីជំនួយនោះតម្រូវឱ្យប៊ូតុងបញ្ជាទិញ និងប្រអប់ធីកស្របច្បាប់បង្ហាញនៅខាងក្រោមសេចក្តីសង្ខេបនៃការបញ្ជាទិញ។','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ទីតាំងបញ្ជាទិញត្រូវបានកំណត់ទៅ &quot;នៅខាងក្រោមសេចក្តីសង្ខេបនៃការបញ្ជាទិញ&quot; ជានិច្ចនៅពេលប្រើ Germanized សម្រាប់ WooCommerce។ កម្មវិធីជំនួយនោះតម្រូវឱ្យប៊ូតុងបញ្ជាទិញ និងប្រអប់ធីកស្របច្បាប់ត្រូវបានបង្ហាញនៅខាងក្រោមសេចក្តីសង្ខេបនៃការបញ្ជាទិញ។','Edit pickup locations' => 'កែសម្រួលទីតាំងទទួល','Use local pickup label from WooCommerce settings' => 'ប្រើប្រាស់ស្លាកទទួលទំនិញក្នុងស្រុកពីការកំណត់ WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'នៅពេលបើកដំណើរការ ស្លាកជម្រើសទទួលយកនៅពេលទូទាត់ប្រាក់ត្រូវគ្នានឹងចំណងជើងពីការកំណត់ទីតាំងទទួលយករបស់ WooCommerce។ នៅពេលបិទដំណើរការ ស្លាកនឹងប្រើអត្ថបទ &quot;ទទួលយកក្នុងស្រុក&quot; ដែលអាចបកប្រែបានពី Fluid Checkout។','Button label for applying coupon codesApply' => 'អនុវត្ត','Checkout step titleContact' => 'ទំនាក់ទំនង','Checkout step titleShipping' => 'ការដឹកជញ្ជូន','Checkout step titleBilling' => 'វិក័យប័ត្រ','Checkout step titlePayment' => 'ការទូទាត់','Checkout substep change link labelChange' => 'ផ្លាស់ប្តូរ','Checkout substep save link labelSave changes' => 'រក្សាទុកការផ្លាស់ប្តូរ','Substep review textNone.' => 'គ្មាន។','Substep review field format%1$s' => '%1$s','Substep review field format: with 